* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background-color: var(--page);
  color: var(--ink);
  font-family: var(--f2);
  min-height: 100vh;
  transition: background-color 0.25s ease, color 0.25s ease;
  overflow-x: hidden;
}

/* Custom Scrollbar for Retro Feel */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: var(--fld);
}
::-webkit-scrollbar-thumb {
  background: var(--dim);
  border-radius: 2px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--a1);
}

/* Typography Helpers */
.font-pixel {
  font-family: var(--px);
}

.font-terminal {
  font-family: var(--vt);
}

/* Authentic CRT Screen Scanlines */
.scanlines-overlay {
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%, 
    rgba(0, 0, 0, 0.2) 50%
  ), linear-gradient(
    90deg,
    rgba(255, 0, 0, 0.02),
    rgba(0, 255, 0, 0.01),
    rgba(0, 0, 255, 0.02)
  );
  background-size: 100% 4px, 6px 100%;
  pointer-events: none;
}

/* Screen CRT curvature / subtle shadow */
.crt-screen-shadow {
  box-shadow: inset 0 0 40px rgba(0, 0, 0, 0.35);
}

/* Arcade Push Button Styling */
.arcade-btn {
  background: var(--a1);
  color: var(--on);
  border-radius: var(--r);
  padding: 8px 18px;
  font-family: var(--f1);
  font-size: 11px;
  text-decoration: none;
  text-align: center;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 2px solid transparent;
  transition: transform 0.08s ease, filter 0.15s ease, background-color 0.15s ease;
  user-select: none;
  letter-spacing: 0.05em;
  box-shadow: 0 4px 0 rgba(0,0,0,0.25);
}

.arcade-btn:hover {
  filter: brightness(1.15);
}

.arcade-btn:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 rgba(0,0,0,0.25);
}

.arcade-btn.alt {
  background: transparent;
  color: var(--ink);
  border: 2px solid var(--dim);
  box-shadow: none;
}

.arcade-btn.alt:hover {
  background: var(--fld);
  border-color: var(--ink);
}

.arcade-btn.blink {
  animation: arcade-blink 1.2s steps(2) infinite;
}

@keyframes arcade-blink {
  50% {
    opacity: 0.55;
  }
}

/* Theme Grid Swatches */
.tc-button {
  all: unset;
  box-sizing: border-box;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  padding: 6px;
  border: 3px solid transparent;
  border-radius: var(--r);
  transition: all 0.15s ease;
}

.tc-button:hover {
  transform: translateY(-2px);
}

.tc-button.on {
  border-color: var(--a1);
  box-shadow: 0 0 12px rgba(0,0,0,0.3);
}

/* Crosshair & Target Reticle */
.reticle-cross {
  position: relative;
  width: 32px;
  height: 32px;
  border: 2px solid var(--ink);
  border-radius: 50%;
}
.reticle-cross::before {
  content: "";
  position: absolute;
  left: 14px;
  top: -8px;
  width: 2px;
  height: 48px;
  background: var(--ink);
}
.reticle-cross::after {
  content: "";
  position: absolute;
  top: 14px;
  left: -8px;
  height: 2px;
  width: 48px;
  background: var(--ink);
}

/* Gaze Ring */
.gaze-ring {
  width: 28px;
  height: 28px;
  border: 2px dashed var(--a1);
  border-radius: 50%;
  animation: spin-gaze 6s linear infinite;
}

@keyframes spin-gaze {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* Tunnel wall stripes */
.tunnel-wall {
  background: repeating-linear-gradient(
    135deg,
    var(--dim) 0 8px,
    var(--line) 8px 16px
  );
}

/* Dial Slider Notched Track */
.dial-track {
  --nt: 6px;
  position: relative;
  height: 52px;
  background: var(--dial);
  cursor: grab;
  touch-action: pan-y;
  user-select: none;
  clip-path: polygon(
    var(--nt) 0,
    calc(100% - var(--nt)) 0,
    calc(100% - var(--nt)) var(--nt),
    100% var(--nt),
    100% calc(100% - var(--nt)),
    calc(100% - var(--nt)) calc(100% - var(--nt)),
    calc(100% - var(--nt)) 100%,
    var(--nt) 100%,
    var(--nt) calc(100% - var(--nt)),
    0 calc(100% - var(--nt)),
    0 var(--nt),
    var(--nt) var(--nt)
  );
}

.dial-track:active {
  cursor: grabbing;
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { playSound, toggleAudioMute, isAudioMuted } from '../utils/audio';

export type StepId = 
  | 'style' 
  | 'start' 
  | 'profile' 
  | 'warmup' 
  | 'howto' 
  | 'mission1' 
  | 'mission2' 
  | 'results' 
  | 'operator';

export const STEP_IDS: StepId[] = [
  'style',
  'start',
  'profile',
  'warmup',
  'howto',
  'mission1',
  'mission2',
  'results',
  'operator',
];

export const STEP_NAMES = [
  'STYLE',
  'START',
  'PROFILE',
  'WARM-UP',
  'HOW TO PLAY',
  'TARGET LOCK',
  'COMET TUNNEL',
  'PILOT CARD',
  'OPERATOR',
];

export interface PlayerProfile {
  nickname: string;
  ageGroup: string;
  writingHand: 'Left' | 'Right';
  glasses: 'No' | 'Yes';
  consentAdult: boolean;
  consentPrivacy: boolean;
}

export interface Mission1Log {
  id: number;
  label: string;
  type: 'Round' | 'Square';
  text: string;
  gapMs?: number;
  success: boolean;
}

export interface RecentRun {
  id: string;
  age: string;
  focusScore: number;
  gapMs: number;
  steadyPct: number;
  status: 'OK' | 'REVIEW';
  timestamp: string;
}

interface ArcadeContextType {
  themeId: number;
  setThemeId: (id: number) => void;
  currentStep: number; // 1-indexed (1 to 9)
  stepId: StepId;
  goToStep: (step: number | StepId) => void;
  nextStep: () => void;
  prevStep: () => void;
  playerProfile: PlayerProfile;
  setPlayerProfile: React.Dispatch<React.SetStateAction<PlayerProfile>>;

  // Audio
  soundMuted: boolean;
  toggleMute: () => void;

  // Warm-up calibration
  calibrationPoint: number;
  advanceCalibration: () => void;
  isCalibrated: boolean;
  resetCalibration: () => void;

  // Mission 1 State
  m1Time: number;
  m1Score: number;
  m1Streak: number;
  m1GapMs: number;
  m1Logs: Mission1Log[];
  recordM1Hit: (type: 'Round' | 'Square', reactionMs: number) => void;
  resetMission1: () => void;

  // Mission 2 State
  m2Time: number;
  m2Steady: number;
  m2OnPath: number;
  m2EyesOnComet: number;
  m2TremorPoints: number[];
  m2CatchUpJumps: number;
  updateM2Tremor: (val: number, inPath: boolean, eyesLocked: boolean) => void;
  resetMission2: () => void;

  // Results & Operator Runs
  recentRuns: RecentRun[];
  exportRunsCSV: () => void;
  saveCurrentRun: () => void;
  savedToTigerData: boolean;
}

const INITIAL_RUNS: RecentRun[] = [
  { id: '#014', age: '8–10', focusScore: 92, gapMs: 235, steadyPct: 94, status: 'OK', timestamp: '2m ago' },
  { id: '#013', age: '5–7', focusScore: 71, gapMs: 318, steadyPct: 63, status: 'REVIEW', timestamp: '14m ago' },
  { id: '#012', age: '11–13', focusScore: 88, gapMs: 254, steadyPct: 90, status: 'OK', timestamp: '28m ago' },
  { id: '#011', age: '8–10', focusScore: 79, gapMs: 287, steadyPct: 81, status: 'OK', timestamp: '45m ago' },
];

const ArcadeContext = createContext<ArcadeContextType | undefined>(undefined);

export const ArcadeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [themeId, setThemeIdState] = useState<number>(1);
  const [currentStep, setCurrentStep] = useState<number>(1);
  const [soundMuted, setSoundMuted] = useState<boolean>(isAudioMuted());

  // Player Profile
  const [playerProfile, setPlayerProfile] = useState<PlayerProfile>({
    nickname: 'PILOT_042',
    ageGroup: '8–10',
    writingHand: 'Right',
    glasses: 'Yes',
    consentAdult: true,
    consentPrivacy: true,
  });

  // Warmup Calibration (1 to 5)
  const [calibrationPoint, setCalibrationPoint] = useState<number>(1);
  const [isCalibrated, setIsCalibrated] = useState<boolean>(false);

  // Mission 1 State
  const [m1Time, setM1Time] = useState<number>(20);
  const [m1Score, setM1Score] = useState<number>(420);
  const [m1Streak, setM1Streak] = useState<number>(4);
  const [m1GapMs, setM1GapMs] = useState<number>(240);
  const [m1Logs, setM1Logs] = useState<Mission1Log[]>([
    { id: 7, label: '#7 Round', type: 'Round', text: '232 ms', gapMs: 232, success: true },
    { id: 6, label: '#6 Square', type: 'Square', text: 'Skipped', success: true },
    { id: 5, label: '#5 Round', type: 'Round', text: '251 ms', gapMs: 251, success: true },
    { id: 4, label: '#4 Square', type: 'Square', text: 'Pressed', success: false },
    { id: 3, label: '#3 Round', type: 'Round', text: '228 ms', gapMs: 228, success: true },
  ]);

  // Mission 2 State
  const [m2Time, setM2Time] = useState<number>(30);
  const [m2Steady, setM2Steady] = useState<number>(94);
  const [m2OnPath, setM2OnPath] = useState<number>(88);
  const [m2EyesOnComet, setM2EyesOnComet] = useState<number>(91);
  const [m2CatchUpJumps, setM2CatchUpJumps] = useState<number>(2);
  const [m2TremorPoints, setM2TremorPoints] = useState<number[]>([
    14, 10, 15, 9, 13, 8, 12, 16, 10, 13, 9, 14, 11, 15, 10, 12, 11
  ]);

  // Operator Runs & TigerData
  const [recentRuns, setRecentRuns] = useState<RecentRun[]>(INITIAL_RUNS);
  const [savedToTigerData, setSavedToTigerData] = useState<boolean>(true);

  // Apply data-t attribute to document.body
  const setThemeId = (id: number) => {
    setThemeIdState(id);
    document.body.setAttribute('data-t', id.toString());
    playSound('step');
  };

  useEffect(() => {
    document.body.setAttribute('data-t', themeId.toString());
  }, [themeId]);

  const toggleMute = () => {
    const next = toggleAudioMute();
    setSoundMuted(next);
  };

  const stepId = STEP_IDS[currentStep - 1] || 'style';

  const goToStep = (step: number | StepId) => {
    let target = 1;
    if (typeof step === 'string') {
      const idx = STEP_IDS.indexOf(step);
      target = idx >= 0 ? idx + 1 : 1;
    } else {
      target = Math.max(1, Math.min(STEP_IDS.length, step));
    }
    setCurrentStep(target);
    playSound('step');
  };

  const nextStep = () => {
    if (currentStep < STEP_IDS.length) {
      goToStep(currentStep + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 1) {
      goToStep(currentStep - 1);
    }
  };

  // Calibration helpers
  const advanceCalibration = () => {
    playSound('blip');
    if (calibrationPoint < 5) {
      setCalibrationPoint(prev => prev + 1);
    } else {
      setIsCalibrated(true);
      playSound('win');
    }
  };

  const resetCalibration = () => {
    setCalibrationPoint(1);
    setIsCalibrated(false);
  };

  // Mission 1 helpers
  const recordM1Hit = (type: 'Round' | 'Square', reactionMs: number) => {
    if (type === 'Round') {
      playSound('hit');
      setM1Score(prev => prev + 100 * Math.max(1, m1Streak));
      setM1Streak(prev => Math.min(10, prev + 1));
      setM1GapMs(reactionMs);
      setM1Logs(prev => [
        {
          id: prev.length + 1,
          label: `#${prev.length + 1} Round`,
          type: 'Round',
          text: `${reactionMs} ms`,
          gapMs: reactionMs,
          success: true,
        },
        ...prev.slice(0, 7),
      ]);
    } else {
      // Trick square target hit (Impulse penalty)
      playSound('error');
      setM1Score(prev => Math.max(0, prev - 50));
      setM1Streak(1);
      setM1Logs(prev => [
        {
          id: prev.length + 1,
          label: `#${prev.length + 1} Square`,
          type: 'Square',
          text: 'Pressed',
          success: false,
        },
        ...prev.slice(0, 7),
      ]);
    }
  };

  const resetMission1 = () => {
    setM1Time(20);
    setM1Score(0);
    setM1Streak(1);
    setM1GapMs(240);
  };

  // Mission 2 helpers
  const updateM2Tremor = (jitterVal: number, inPath: boolean, eyesLocked: boolean) => {
    setM2TremorPoints(prev => [...prev.slice(1), Math.round(jitterVal)]);
    if (!inPath) {
      setM2OnPath(prev => Math.max(50, prev - 0.5));
      setM2Steady(prev => Math.max(60, prev - 0.3));
    }
    if (!eyesLocked) {
      setM2EyesOnComet(prev => Math.max(65, prev - 0.4));
      setM2CatchUpJumps(prev => prev + 1);
    }
  };

  const resetMission2 = () => {
    setM2Time(30);
    setM2Steady(94);
    setM2OnPath(88);
    setM2EyesOnComet(91);
    setM2CatchUpJumps(2);
  };

  // Operator CSV Export
  const exportRunsCSV = () => {
    playSound('coin');
    const headers = ['RunID', 'AgeGroup', 'WritingHand', 'Glasses', 'FocusScore', 'LatencyGapMs', 'MotorSteadinessPct', 'Status', 'Timestamp'];
    const rows = recentRuns.map(r => [
      r.id,
      r.age,
      playerProfile.writingHand,
      playerProfile.glasses,
      r.focusScore,
      r.gapMs,
      r.steadyPct,
      r.status,
      r.timestamp,
    ]);

    const csvContent = [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `AeroNeuro_Runs_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const saveCurrentRun = () => {
    playSound('coin');
    setSavedToTigerData(true);
    const newRun: RecentRun = {
      id: `#0${recentRuns.length + 11}`,
      age: playerProfile.ageGroup,
      focusScore: Math.min(100, Math.round((m1Score / 600) * 100) || 92),
      gapMs: m1GapMs,
      steadyPct: Math.round(m2Steady),
      status: m2Steady >= 80 && m1GapMs < 290 ? 'OK' : 'REVIEW',
      timestamp: 'Just now',
    };
    setRecentRuns(prev => [newRun, ...prev]);
  };

  return (
    <ArcadeContext.Provider
      value={{
        themeId,
        setThemeId,
        currentStep,
        stepId,
        goToStep,
        nextStep,
        prevStep,
        playerProfile,
        setPlayerProfile,
        soundMuted,
        toggleMute,
        calibrationPoint,
        advanceCalibration,
        isCalibrated,
        resetCalibration,
        m1Time,
        m1Score,
        m1Streak,
        m1GapMs,
        m1Logs,
        recordM1Hit,
        resetMission1,
        m2Time,
        m2Steady,
        m2OnPath,
        m2EyesOnComet,
        m2TremorPoints,
        m2CatchUpJumps,
        updateM2Tremor,
        resetMission2,
        recentRuns,
        exportRunsCSV,
        saveCurrentRun,
        savedToTigerData,
      }}
    >
      {children}
    </ArcadeContext.Provider>
  );
};

export const useArcade = () => {
  const context = useContext(ArcadeContext);
  if (!context) {
    throw new Error('useArcade must be used within an ArcadeProvider');
  }
  return context;
};

import React, { useRef, useState } from 'react';
import { useArcade, STEP_NAMES } from '../../context/ArcadeContext';

export const BottomDial: React.FC = () => {
  const { currentStep, goToStep } = useArcade();
  const trackRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const totalSteps = STEP_NAMES.length;

  const getStepFromPointer = (clientX: number): number => {
    if (!trackRef.current) return currentStep;
    const rect = trackRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(rect.width, clientX - rect.left));
    const step = Math.floor((x / rect.width) * totalSteps) + 1;
    return Math.max(1, Math.min(totalSteps, step));
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    setIsDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
    const newStep = getStepFromPointer(e.clientX);
    goToStep(newStep);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!isDragging) return;
    const newStep = getStepFromPointer(e.clientX);
    if (newStep !== currentStep) {
      goToStep(newStep);
    }
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    if (isDragging) {
      setIsDragging(false);
      try {
        e.currentTarget.releasePointerCapture(e.pointerId);
      } catch {
        // ignore
      }
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'ArrowRight' && currentStep < totalSteps) {
      goToStep(currentStep + 1);
    } else if (e.key === 'ArrowLeft' && currentStep > 1) {
      goToStep(currentStep - 1);
    }
  };

  return (
    <div className="mt-3 w-full">
      {/* 9-Notch Dial Slider Track */}
      <div
        ref={trackRef}
        role="slider"
        tabIndex={0}
        aria-label="Arcade Kiosk Screen Step"
        aria-valuemin={1}
        aria-valuemax={totalSteps}
        aria-valuenow={currentStep}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
        onKeyDown={handleKeyDown}
        className="dial-track relative grid grid-cols-9 h-12 sm:h-14 bg-[var(--dial)] outline-none transition-all shadow-inner border border-black/20"
      >
        {/* Sliding Thumb Indicator */}
        <div
          className="absolute top-0 bottom-0 border-4 border-transparent bg-[var(--btn)] transition-all duration-200 ease-out shadow-[inset_-3px_-3px_0_rgba(0,0,0,0.35)] rounded-[2px] pointer-events-none"
          style={{
            left: `${((currentStep - 1) / totalSteps) * 100}%`,
            width: `${100 / totalSteps}%`,
          }}
        />

        {/* 9 Steps Labels */}
        {STEP_NAMES.map((name, idx) => {
          const stepNumber = idx + 1;
          const isActive = stepNumber === currentStep;

          return (
            <div
              key={name}
              className={`relative z-10 flex items-center justify-center gap-1 sm:gap-1.5 px-1 font-pixel text-[8px] sm:text-[9px] md:text-[10px] tracking-tight transition-colors duration-150 select-none ${
                isActive
                  ? 'text-[var(--btnink)] font-bold drop-shadow'
                  : 'text-[var(--dialink)] hover:text-[var(--ink)]'
              }`}
            >
              <span className={`text-[10px] sm:text-xs font-terminal ${isActive ? 'opacity-100 font-bold' : 'opacity-60'}`}>
                {stepNumber}
              </span>
              <span className="hidden md:inline whitespace-nowrap">
                {name}
              </span>
            </div>
          );
        })}
      </div>

      {/* Step Caption / Keyboard navigation helper */}
      <div className="flex items-center justify-between text-[11px] font-pixel text-[var(--mqc)] mt-2 px-1">
        <span>STEP {currentStep} OF {totalSteps} · {STEP_NAMES[currentStep - 1]}</span>
        <span className="hidden sm:inline opacity-70">USE ← / → ARROWS TO SCRUB</span>
      </div>
    </div>
  );
};

