import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import { ArcadeProvider } from './context/ArcadeContext';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <ArcadeProvider>
      <App />
    </ArcadeProvider>
  </React.StrictMode>
);

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: dark;
  box-sizing: border-box;
  --px: "Press Start 2P", monospace;
  --vt: "VT323", monospace;
  --f1: var(--px);
  --f2: var(--vt);
  --r: 6px;
}

/* THEME 1: MOON ROCK (Default - enhanced contrast) */
body, body[data-t="1"], .theme-1 {
  --page: #7b8694;
  --body: #d4dae2;
  --bezel: #353c48;
  --scr: #e8eef4;
  --fld: #dbe2ea;
  --ink: #0f1722;
  --dim: #475569;
  --line: #b0becd;
  --a1: #0f1722;
  --good: #1a5682;
  --bad: #b91c1c;
  --on: #ffffff;
  --dial: #cbd5e1;
  --dialink: #334155;
  --btn: #0f1722;
  --btnink: #f8fafc;
  --mqc: #64748b;
}

/* THEME 2: SUNSET */
body[data-t="2"], .theme-2 {
  --page: #0f0f10;
  --body: #242426;
  --bezel: #0a0a0c;
  --scr: #191610;
  --fld: #221e15;
  --ink: #ffc83b;
  --dim: #d4a338;
  --line: #42381e;
  --a1: #ffc83b;
  --good: #ffd666;
  --bad: #ff6b4a;
  --on: #191610;
  --dial: #1f1f22;
  --dialink: #c49936;
  --btn: #ffc83b;
  --btnink: #14120c;
  --mqc: #9e7d32;
}

/* THEME 3: DEEP SEA */
body[data-t="3"], .theme-3 {
  --page: #131722;
  --body: #bfc5d0;
  --bezel: #1e2433;
  --scr: #0b1424;
  --fld: #121f35;
  --ink: #f0f6ff;
  --dim: #a5bdd9;
  --line: #223753;
  --a1: #60b5ff;
  --good: #60b5ff;
  --bad: #ff7866;
  --on: #08101e;
  --dial: #a8b2c2;
  --dialink: #2a384c;
  --btn: #0b1424;
  --btnink: #f0f6ff;
  --mqc: #5c6c82;
}

/* THEME 4: CLOUD */
body[data-t="4"], .theme-4 {
  --page: #b5b0a3;
  --body: #e5e0d3;
  --bezel: #595752;
  --scr: #f8f6ee;
  --fld: #ece8db;
  --ink: #0a0a0a;
  --dim: #57544c;
  --line: #ccc6b3;
  --a1: #0a0a0a;
  --good: #0a0a0a;
  --bad: #c82820;
  --on: #ffffff;
  --dial: #d6d0c1;
  --dialink: #4f4c45;
  --btn: #0a0a0a;
  --btnink: #f8f6ee;
  --mqc: #878276;
  color-scheme: light;
}

/* THEME 5: COMET */
body[data-t="5"], .theme-5 {
  --page: #202024;
  --body: #323238;
  --bezel: #121214;
  --scr: #242429;
  --fld: #2b2b32;
  --ink: #f8f8f8;
  --dim: #bcbcc8;
  --line: #42424c;
  --a1: #f8f8f8;
  --good: #f5c442;
  --bad: #ff6e5e;
  --on: #202024;
  --dial: #28282e;
  --dialink: #b2b2bf;
  --btn: #f5c442;
  --btnink: #1a1a1f;
  --mqc: #8e8e9c;
}

/* THEME 6: NEON */
body[data-t="6"], .theme-6 {
  --page: #06030b;
  --body: #0c0616;
  --bezel: #4c299c;
  --scr: #10091d;
  --fld: #190e2e;
  --ink: #faf2fe;
  --dim: #cbb4ee;
  --line: #332252;
  --a1: #ff52ad;
  --good: #ff52ad;
  --bad: #b294fc;
  --on: #0c0616;
  --dial: #180f2b;
  --dialink: #c2abe3;
  --btn: #ff52ad;
  --btnink: #0c0616;
  --mqc: #8960e6;
}

* {
  box-sizing: border-box;
}

html, body {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--page);
  color: var(--ink);
  font-family: var(--f2);
  transition: background-color 0.25s ease, color 0.25s ease;
  overflow: hidden;
}

/* Typography Helpers */
.font-pixel {
  font-family: var(--px);
}

.font-terminal {
  font-family: var(--vt);
}

/* Scanlines: made significantly paler for high readability */
.scanlines-overlay {
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%, 
    rgba(0, 0, 0, 0.08) 50%
  ), linear-gradient(
    90deg,
    rgba(255, 0, 0, 0.015),
    rgba(0, 255, 0, 0.01),
    rgba(0, 0, 255, 0.015)
  );
  background-size: 100% 4px, 6px 100%;
  pointer-events: none;
}

/* CRT Screen curvature shadow */
.crt-screen-shadow {
  box-shadow: inset 0 0 50px rgba(0, 0, 0, 0.3);
}

/* Arcade Push Button Styling (Larger, more comfortable click targets) */
.arcade-btn {
  background: var(--a1);
  color: var(--on);
  border-radius: var(--r);
  padding: 10px 22px;
  font-family: var(--f1);
  font-size: 13px;
  text-decoration: none;
  text-align: center;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 2px solid transparent;
  transition: transform 0.08s ease, filter 0.15s ease, background-color 0.15s ease;
  user-select: none;
  letter-spacing: 0.05em;
  box-shadow: 0 4px 0 rgba(0,0,0,0.3);
}

.arcade-btn:hover {
  filter: brightness(1.15);
}

.arcade-btn:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 rgba(0,0,0,0.3);
}

.arcade-btn.alt {
  background: transparent;
  color: var(--ink);
  border: 2px solid var(--dim);
  box-shadow: none;
}

.arcade-btn.alt:hover {
  background: var(--fld);
  border-color: var(--ink);
}

.arcade-btn.blink {
  animation: arcade-blink 1.2s steps(2) infinite;
}

@keyframes arcade-blink {
  50% {
    opacity: 0.55;
  }
}

/* Crosshair & Target Reticle */
.reticle-cross {
  position: relative;
  width: 44px;
  height: 44px;
  border: 3px solid var(--ink);
  border-radius: 50%;
}
.reticle-cross::before {
  content: "";
  position: absolute;
  left: 19px;
  top: -12px;
  width: 3px;
  height: 68px;
  background: var(--ink);
}
.reticle-cross::after {
  content: "";
  position: absolute;
  top: 19px;
  left: -12px;
  height: 3px;
  width: 68px;
  background: var(--ink);
}

/* Gaze Ring */
.gaze-ring {
  width: 36px;
  height: 36px;
  border: 2px dashed var(--a1);
  border-radius: 50%;
  animation: spin-gaze 6s linear infinite;
}

@keyframes spin-gaze {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* Tunnel wall stripes */
.tunnel-wall {
  background: repeating-linear-gradient(
    135deg,
    var(--dim) 0 10px,
    var(--line) 10px 20px
  );
}

/* Dial Slider Notched Track */
.dial-track {
  --nt: 6px;
  position: relative;
  height: 52px;
  background: var(--dial);
  cursor: grab;
  touch-action: pan-y;
  user-select: none;
  clip-path: polygon(
    var(--nt) 0,
    calc(100% - var(--nt)) 0,
    calc(100% - var(--nt)) var(--nt),
    100% var(--nt),
    100% calc(100% - var(--nt)),
    calc(100% - var(--nt)) calc(100% - var(--nt)),
    calc(100% - var(--nt)) 100%,
    var(--nt) 100%,
    var(--nt) calc(100% - var(--nt)),
    0 calc(100% - var(--nt)),
    0 var(--nt),
    var(--nt) var(--nt)
  );
}

.dial-track:active {
  cursor: grabbing;
}

import React, { useEffect, useRef, useState } from 'react';
import { Camera, CameraOff, Eye, Maximize2, Minimize2 } from 'lucide-react';

interface CameraFeedProps {
  className?: string;
}

export const CameraFeed: React.FC<CameraFeedProps> = ({ className = '' }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [streamActive, setStreamActive] = useState<boolean>(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [minimized, setMinimized] = useState<boolean>(false);

  useEffect(() => {
    let stream: MediaStream | null = null;

    async function initCamera() {
      try {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
          setErrorMsg('Webcam API not supported in this browser');
          return;
        }

        stream = await navigator.mediaDevices.getUserMedia({
          video: {
            width: { ideal: 320 },
            height: { ideal: 240 },
            facingMode: 'user',
          },
          audio: false,
        });

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play().catch(() => {});
          setStreamActive(true);
          setErrorMsg(null);
        }
      } catch (err: unknown) {
        console.warn('Webcam stream unavailable:', err);
        setErrorMsg('Camera access needed or offline');
        setStreamActive(false);
      }
    }

    initCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  return (
    <div
      className={`absolute z-40 transition-all duration-200 select-none ${
        minimized
          ? 'bottom-3 right-3 w-32 h-10'
          : 'bottom-3 right-3 w-48 sm:w-56 h-36 sm:h-44'
      } bg-[#0b0f19]/95 border-2 border-[var(--dim)] rounded-lg shadow-2xl overflow-hidden flex flex-col ${className}`}
    >
      {/* Top Header Strip */}
      <div className="flex items-center justify-between px-2 py-1 bg-[var(--bezel)] text-[var(--scr)] text-[10px] sm:text-[11px] font-terminal border-b border-black/40">
        <div className="flex items-center gap-1.5 font-bold">
          <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
          <span>QNX CAM</span>
          <span className="text-[9px] text-[var(--good)] opacity-90">60 FPS</span>
        </div>

        <button
          onClick={() => setMinimized(!minimized)}
          className="text-[var(--scr)] hover:text-white p-0.5 rounded"
          title={minimized ? 'Expand Camera' : 'Minimize Camera'}
        >
          {minimized ? <Maximize2 className="w-3 h-3" /> : <Minimize2 className="w-3 h-3" />}
        </button>
      </div>

      {/* Video Content or Fallback */}
      {!minimized && (
        <div className="relative flex-1 bg-black overflow-hidden flex items-center justify-center">
          {streamActive ? (
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              className="w-full h-full object-cover -scale-x-100"
            />
          ) : (
            <div className="flex flex-col items-center justify-center text-center p-2 space-y-1">
              <CameraOff className="w-6 h-6 text-[var(--dim)]" />
              <span className="text-[10px] font-terminal text-[var(--dim)] leading-tight">
                {errorMsg || 'Simulated QNX Vision Feed'}
              </span>
              <span className="text-[9px] font-pixel text-[var(--good)]">
                TRACKING: MOCK
              </span>
            </div>
          )}

          {/* Simulated QNX Facial Landmark & Eye-Center Tracking Overlays */}
          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
            {/* Eye Bounding Reticle */}
            <div className="relative w-28 h-10 border border-emerald-400/70 rounded-sm flex items-center justify-around px-2 animate-pulse">
              {/* Left Eye Dot */}
              <div className="w-2.5 h-2.5 rounded-full border border-cyan-400 bg-cyan-400/40 flex items-center justify-center">
                <div className="w-1 h-1 rounded-full bg-white" />
              </div>

              {/* Right Eye Dot */}
              <div className="w-2.5 h-2.5 rounded-full border border-cyan-400 bg-cyan-400/40 flex items-center justify-center">
                <div className="w-1 h-1 rounded-full bg-white" />
              </div>

              {/* Landmark crosshairs */}
              <span className="absolute -top-3 left-1 text-[8px] font-pixel text-emerald-400">
                PEDIATRIC EYE-LOCK
              </span>
            </div>
          </div>

          {/* Offline privacy badge */}
          <div className="absolute bottom-1 left-1.5 flex items-center gap-1 text-[9px] font-terminal bg-black/70 px-1.5 py-0.5 rounded text-emerald-300">
            <Eye className="w-2.5 h-2.5" />
            <span>100% OFFLINE</span>
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { useArcade } from './context/ArcadeContext';
import { TopBar } from './components/common/TopBar';
import { BottomDial } from './components/common/BottomDial';
import { CameraFeed } from './components/common/CameraFeed';
import { StyleScreen } from './components/screens/StyleScreen';
import { StartScreen } from './components/screens/StartScreen';
import { ProfileScreen } from './components/screens/ProfileScreen';
import { WarmupScreen } from './components/screens/WarmupScreen';
import { HowToScreen } from './components/screens/HowToScreen';
import { Mission1Screen } from './components/screens/Mission1Screen';
import { Mission2Screen } from './components/screens/Mission2Screen';
import { ResultsScreen } from './components/screens/ResultsScreen';
import { OperatorScreen } from './components/screens/OperatorScreen';

export const AppContent: React.FC = () => {
  const { currentStep } = useArcade();

  return (
    <div className="h-screen w-screen flex flex-col items-center justify-between p-2 sm:p-3 bg-[var(--page)] transition-colors duration-200 overflow-hidden select-none">

      {/* Arcade Kiosk Cabinet Body - Expanded to fill screen */}
      <main className="w-full max-w-[1500px] flex-1 flex flex-col bg-[var(--body)] border-2 border-black/40 rounded-2xl md:rounded-3xl shadow-[0_12px_45px_rgba(0,0,0,0.5)] p-2.5 sm:p-4 transition-colors duration-200 overflow-hidden min-h-0">

        {/* Top Header Bar */}
        <TopBar />

        {/* CRT Screen Frame & Bezel - Fills available height */}
        <div className="relative flex-1 bg-[var(--scr)] border-[10px] sm:border-[14px] md:border-[16px] border-[var(--bezel)] rounded-xl overflow-hidden crt-screen-shadow flex flex-col my-1.5 transition-colors duration-200 min-h-0">

          {/* Very pale CRT scanline overlay */}
          <div className="absolute inset-0 scanlines-overlay z-30 pointer-events-none opacity-20" />

          {/* Live Camera Feed in the corner */}
          <CameraFeed />

          {/* Screen Content Switcher */}
          <div className="relative z-10 flex-1 flex flex-col h-full overflow-hidden">
            {currentStep === 1 && <StyleScreen />}
            {currentStep === 2 && <StartScreen />}
            {currentStep === 3 && <ProfileScreen />}
            {currentStep === 4 && <WarmupScreen />}
            {currentStep === 5 && <HowToScreen />}
            {currentStep === 6 && <Mission1Screen />}
            {currentStep === 7 && <Mission2Screen />}
            {currentStep === 8 && <ResultsScreen />}
            {currentStep === 9 && <OperatorScreen />}
          </div>

        </div>

        {/* 9-Step Arcade Slider Dial at the Bottom */}
        <BottomDial />

      </main>

    </div>
  );
};

export const App: React.FC = () => {
  return <AppContent />;
};

export default App;

import React from 'react';
import { useArcade } from '../../context/ArcadeContext';
import { playSound } from '../../utils/audio';
import { Sparkles, ArrowRight } from 'lucide-react';

export const ProfileScreen: React.FC = () => {
  const { playerProfile, setPlayerProfile, nextStep } = useArcade();

  const handleChipSelect = <K extends keyof typeof playerProfile>(
    key: K,
    value: typeof playerProfile[K]
  ) => {
    playSound('step');
    setPlayerProfile(prev => ({ ...prev, [key]: value }));
  };

  const handleRandomizeNick = () => {
    playSound('step');
    const num = Math.floor(Math.random() * 900 + 100);
    const prefixes = ['PILOT', 'CADET', 'STAR', 'NOVA', 'EAGLE', 'COSMO'];
    const prefix = prefixes[Math.floor(Math.random() * prefixes.length)];
    setPlayerProfile(prev => ({ ...prev, nickname: `${prefix}_${num}` }));
  };

  return (
    <div className="flex flex-col h-full justify-between gap-3 p-4 sm:p-6 md:p-8 overflow-y-auto">

      {/* Top Header */}
      <div className="flex items-center justify-between font-terminal text-sm sm:text-base text-[var(--dim)] uppercase tracking-wider border-b border-[var(--line)] pb-1.5">
        <span>Player setup</span>
        <span>Step 3 of 9</span>
      </div>

      {/* Main Form: Centered and Expanded */}
      <div className="grid md:grid-cols-[1.8fr_1fr] gap-6 sm:gap-8 flex-1 items-center max-w-5xl mx-auto w-full my-auto">

        {/* Left Column: Big Questions */}
        <div className="flex flex-col gap-5 sm:gap-6">
          <div className="space-y-1">
            <h1 className="font-pixel text-xl sm:text-2xl md:text-3xl text-[var(--a1)] tracking-wide">
              WHO’S PLAYING?
            </h1>
            <p className="font-terminal text-base sm:text-lg text-[var(--dim)]">
              Customize your cadet profile before beginning eye-hand testing.
            </p>
          </div>

          {/* 1. Nickname */}
          <div className="space-y-1.5">
            <label className="font-terminal text-sm sm:text-base uppercase tracking-widest text-[var(--dim)] font-bold block">
              1. Cadet Nickname
            </label>
            <div className="flex items-center gap-3">
              <input
                type="text"
                value={playerProfile.nickname}
                onChange={(e) => setPlayerProfile(prev => ({ ...prev, nickname: e.target.value.toUpperCase().slice(0, 12) }))}
                className="border-3 border-[var(--ink)] bg-[var(--scr)] px-4 py-2 font-terminal text-xl sm:text-2xl text-[var(--ink)] rounded-[var(--r)] focus:outline-none focus:border-[var(--a1)] uppercase w-60 tracking-wider shadow-sm"
              />
              <button
                type="button"
                onClick={handleRandomizeNick}
                className="arcade-btn alt font-terminal text-sm sm:text-base py-2 px-4 flex items-center gap-1.5"
              >
                <Sparkles className="w-4 h-4 text-[var(--good)]" />
                <span>Randomize</span>
              </button>
            </div>
          </div>

          {/* 2. Age Group */}
          <div className="space-y-2">
            <label className="font-terminal text-sm sm:text-base uppercase tracking-widest text-[var(--dim)] font-bold block">
              2. Age Group (Select yours)
            </label>
            <div className="flex flex-wrap gap-2 sm:gap-3">
              {['5–7', '8–10', '11–13', '14–17'].map((age) => {
                const isSelected = playerProfile.ageGroup === age;
                return (
                  <button
                    key={age}
                    type="button"
                    onClick={() => handleChipSelect('ageGroup', age)}
                    className={`px-5 py-2.5 font-terminal text-lg sm:text-xl rounded-[var(--r)] border-2 transition-all cursor-pointer select-none ${
                      isSelected
                        ? 'bg-[var(--a1)] text-[var(--on)] border-[var(--a1)] font-bold shadow-md scale-105'
                        : 'border-[var(--dim)] text-[var(--ink)] hover:border-[var(--ink)] bg-[var(--fld)]/50'
                    }`}
                  >
                    {age} Years
                  </button>
                );
              })}
            </div>
          </div>

          {/* 3. Handedness & Glasses */}
          <div className="grid sm:grid-cols-2 gap-4">
            {/* Writing Hand */}
            <div className="space-y-2">
              <label className="font-terminal text-sm sm:text-base uppercase tracking-widest text-[var(--dim)] font-bold block">
                3. Writing Hand
              </label>
              <div className="flex gap-2">
                {(['Left', 'Right'] as const).map((hand) => {
                  const isSelected = playerProfile.writingHand === hand;
                  return (
                    <button
                      key={hand}
                      type="button"
                      onClick={() => handleChipSelect('writingHand', hand)}
                      className={`flex-1 px-4 py-2 font-terminal text-base sm:text-lg rounded-[var(--r)] border-2 transition-all cursor-pointer ${
                        isSelected
                          ? 'bg-[var(--a1)] text-[var(--on)] border-[var(--a1)] font-bold shadow'
