import React, { useState, useEffect, useRef } from 'react';
import { useArcade } from '../../context/ArcadeContext';
import { PixelSprite } from '../common/PixelSprite';
import { playSound } from '../../utils/audio';
import { Crosshair, ArrowRight } from 'lucide-react';

interface TargetInstance {
  id: number;
  type: 'Round' | 'Square';
  x: number; // percentage (10 to 90)
  y: number; // percentage (15 to 80)
  spawnTime: number;
}

export const Mission1Screen: React.FC = () => {
  const {
    m1Score,
    m1Streak,
    m1GapMs,
    m1Logs,
    recordM1Hit,
    nextStep,
  } = useArcade();

  const [timeLeft, setTimeLeft] = useState(20);
  const [currentTarget, setCurrentTarget] = useState<TargetInstance>({
    id: 1,
    type: 'Round',
    x: 65,
    y: 35,
    spawnTime: Date.now(),
  });
  const [crosshairPos, setCrosshairPos] = useState({ x: 50, y: 50 });
  const [hitToast, setHitToast] = useState<{ text: string; good: boolean } | null>(null);
  const arenaRef = useRef<HTMLDivElement>(null);

  // Timer countdown
  useEffect(() => {
    if (timeLeft <= 0) {
      playSound('win');
      nextStep();
      return;
    }
    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft, nextStep]);

  // Target spawning helper
  const spawnNewTarget = () => {
    const isSquare = Math.random() < 0.28; // 28% decoy
    setCurrentTarget({
      id: Date.now(),
      type: isSquare ? 'Square' : 'Round',
      x: Math.floor(Math.random() * 70 + 15),
      y: Math.floor(Math.random() * 60 + 20),
      spawnTime: Date.now(),
    });
  };

  // User zap handler
  const handleTargetClick = (type: 'Round' | 'Square') => {
    const elapsed = Date.now() - currentTarget.spawnTime;
    const simulatedGap = Math.max(160, Math.min(360, elapsed - 40 + Math.floor(Math.random() * 25)));

    recordM1Hit(type, simulatedGap);

    if (type === 'Round') {
      setHitToast({ text: `ZAP! +${100 * Math.max(1, m1Streak)} (${simulatedGap}ms)`, good: true });
    } else {
      setHitToast({ text: 'DECOY TRICK! -50 (Impulse Error)', good: false });
    }

    setTimeout(() => setHitToast(null), 800);
    spawnNewTarget();
  };

  // Crosshair tracking on mouse move
  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!arenaRef.current) return;
    const rect = arenaRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    setCrosshairPos({
      x: Math.max(4, Math.min(96, x)),
      y: Math.max(4, Math.min(96, y)),
    });
  };

  // Keyboard Spacebar fires at crosshair location
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space') {
        e.preventDefault();
        const dx = Math.abs(crosshairPos.x - currentTarget.x);
        const dy = Math.abs(crosshairPos.y - currentTarget.y);
        if (dx < 20 && dy < 20) {
          handleTargetClick(currentTarget.type);
        } else {
          playSound('laser');
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [crosshairPos, currentTarget]);

  return (
    <div className="flex flex-col h-full w-full justify-between gap-1 p-2 sm:p-3 overflow-hidden select-none">

      {/* Top Stats HUD (Gap ms, Time, Score, Streak) */}
      <div className="grid grid-cols-4 gap-2 px-1">
        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-[var(--r)] p-1.5 text-center">
          <span className="font-terminal text-xs text-[var(--dim)] uppercase block">Reaction Gap</span>
          <div className="font-pixel text-base sm:text-xl text-[var(--good)] font-bold">
            {m1GapMs} ms
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-[var(--r)] p-1.5 text-center">
          <span className="font-terminal text-xs text-[var(--dim)] uppercase block">Time Remaining</span>
          <div className="font-pixel text-base sm:text-xl text-[var(--ink)] font-bold">
            0:{timeLeft.toString().padStart(2, '0')}
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-[var(--r)] p-1.5 text-center">
          <span className="font-terminal text-xs text-[var(--dim)] uppercase block">Score</span>
          <div className="font-pixel text-base sm:text-xl text-[var(--good)] font-bold">
            {m1Score}
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-[var(--r)] p-1.5 text-center">
          <span className="font-terminal text-xs text-[var(--dim)] uppercase block">Streak Multiplier</span>
          <div className="font-pixel text-base sm:text-xl text-[var(--a1)] font-bold">
            ×{m1Streak}
          </div>
        </div>
      </div>

      {/* Main Game Area: MASSIVE Arena with a VERY COMPACT Live Log on the right */}
      <div className="grid grid-cols-[1fr_210px] sm:grid-cols-[1fr_240px] gap-2 flex-1 items-stretch my-1 min-h-0">

        {/* HUGE Main Target Arena */}
        <div className="flex flex-col gap-1 min-h-0">

          {/* Target rule chips */}
          <div className="flex items-center gap-2 font-terminal text-xs">
            <span className="bg-[var(--good)] text-[var(--on)] px-3 py-0.5 rounded-[var(--r)] uppercase font-bold">
              Zap round target
            </span>
            <span className="bg-[var(--bad)] text-[var(--on)] px-3 py-0.5 rounded-[var(--r)] uppercase font-bold">
              Skip square decoy (ADHD Impulse Test)
            </span>
            <span className="text-[var(--dim)] ml-auto text-xs hidden sm:inline">
              Click target or press [SPACEBAR] to fire
            </span>
          </div>

          {/* Interactive Arena (Occupies almost the whole screen) */}
          <div
            ref={arenaRef}
            onMouseMove={handleMouseMove}
            className="relative flex-1 rounded-[var(--r)] border-3 border-[var(--dim)] bg-[var(--fld)] overflow-hidden shadow-inner cursor-crosshair min-h-0"
          >
            {/* Very faint, pale grid lines */}
            <div className="absolute inset-0 opacity-10 bg-[radial-gradient(var(--line)_1.5px,transparent_1.5px)] [background-size:28px_28px] pointer-events-none" />

            {/* Hit Feedback Toast */}
            {hitToast && (
              <div className="absolute top-4 inset-x-0 flex justify-center z-30 pointer-events-none">
                <span className={`font-pixel text-xs sm:text-sm px-4 py-1.5 rounded border-2 shadow-xl ${
                  hitToast.good
                    ? 'bg-[var(--good)] text-[var(--on)] border-[var(--on)] animate-bounce'
                    : 'bg-[var(--bad)] text-[var(--on)] border-[var(--on)] animate-pulse'
                }`}>
                  {hitToast.text}
                </span>
              </div>
            )}

            {/* Active Large Target Instance */}
            <div
              style={{ left: `${currentTarget.x}%`, top: `${currentTarget.y}%` }}
              onClick={() => handleTargetClick(currentTarget.type)}
              className="absolute -translate-x-1/2 -translate-y-1/2 cursor-pointer z-20 group"
            >
              <div className="relative p-3 flex items-center justify-center">
                {/* Simulated Gaze Lock Ring around target */}
                <div className="absolute -inset-2 gaze-ring opacity-75 pointer-events-none" />

                {currentTarget.type === 'Round' ? (
                  <PixelSprite
                    name="inv"
                    color="var(--good)"
                    size={5.5}
                    className="group-hover:scale-110 transition-transform drop-shadow-md"
                  />
                ) : (
                  <PixelSprite
                    name="sq"
                    color="var(--bad)"
                    size={5.5}
                    className="group-hover:scale-110 transition-transform drop-shadow-md animate-pulse"
                  />
                )}
              </div>
            </div>

            {/* Big Crosshair following pointer */}
            <div
              style={{ left: `${crosshairPos.x}%`, top: `${crosshairPos.y}%` }}
              className="absolute -translate-x-1/2 -translate-y-1/2 pointer-events-none z-15"
            >
              <div className="reticle-cross opacity-80" />
            </div>

          </div>
        </div>

        {/* COMPACT Right Live Log (Much smaller as requested) */}
        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-[var(--r)] p-2.5 flex flex-col justify-between overflow-hidden">
          <div className="min-h-0 flex-1 flex flex-col">
            <div className="font-terminal text-xs uppercase tracking-widest text-[var(--dim)] font-bold border-b border-[var(--line)] pb-1 mb-1.5">
              QNX Live Log
            </div>

            <div className="space-y-1 font-terminal text-xs sm:text-sm overflow-y-auto pr-1 flex-1">
              {m1Logs.slice(0, 8).map((log) => (
                <div
                  key={log.id}
                  className="flex items-center justify-between border-b border-[var(--line)] pb-0.5"
                >
                  <span className="text-[var(--ink)] truncate">{log.label}</span>
                  <b className={log.success ? 'text-[var(--good)]' : 'text-[var(--bad)]'}>
                    {log.text}
                  </b>
                </div>
              ))}
            </div>
          </div>

          <div className="pt-2 border-t border-[var(--line)] space-y-1.5">
            <div className="text-[10px] font-terminal text-[var(--dim)]">
              RTOS Jitter: &lt; 0.42ms
            </div>
            <button
              onClick={nextStep}
              className="arcade-btn font-pixel text-[10px] py-2 w-full flex items-center justify-center gap-1"
            >
              <span>Next Mission</span>
              <ArrowRight className="w-3 h-3" />
            </button>
          </div>
        </div>

      </div>

      {/* Slim Bottom Status */}
      <div className="flex items-center justify-between px-2 text-[11px] font-terminal text-[var(--dim)]">
        <span>Gaze Snap Clock synced with QNX RTOS edge camera</span>
        <span>Stage 1 of 2 Complete</span>
