            <span className="bg-[var(--dim)] text-[var(--on)] px-3 py-0.5 rounded-[var(--r)] uppercase font-bold">
              Steer ship with [W/S] or [↑/↓]
            </span>
            <span className="text-[var(--dim)] ml-auto text-xs hidden sm:inline">
              Keep hands steady to avoid tremor penalty
            </span>
          </div>

          {/* Interactive Tunnel Field */}
          <div className="relative flex-1 rounded-[var(--r)] border-3 border-[var(--dim)] bg-[var(--fld)] overflow-hidden shadow-inner min-h-0">

            {/* Pale Upper Striped Wall */}
            <div className="tunnel-wall absolute top-0 inset-x-0 h-[20%] border-b-2 border-[var(--dim)] opacity-40" />

