      {/* Slim Bottom Status */}
      <div className="flex items-center justify-between px-2 text-[11px] font-terminal text-[var(--dim)]">
        <span>Dual-Task Smooth Pursuit &amp; Intention Tremor Sensor Feed Active</span>
        <span>Stage 2 of 2 Complete</span>
      </div>

    </div>
  );
};

