* {
  box-sizing: border-box;
}

html, body {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--page);
  color: var(--ink);
  font-family: var(--f-ui);
  transition: background-color 0.25s ease, color 0.25s ease;
  overflow: hidden;
  font-size: 16px;
  line-height: 1.5;
}

/* Clean, readable typography classes (no migraine pixel body text) */
.font-heading {
  font-family: var(--f-heading);
}

.font-ui {
  font-family: var(--f-ui);
}

.font-mono-clean {
  font-family: var(--f-mono);
}

/* Subtle, very pale scanlines that do not cause eye fatigue */
.scanlines-subtle {
  background: linear-gradient(
    rgba(0, 0, 0, 0) 50%, 
    rgba(0, 0, 0, 0.04) 50%
  );
  background-size: 100% 4px;
  pointer-events: none;
}

/* CRT Screen curvature */
.crt-shadow {
  box-shadow: inset 0 0 40px rgba(0, 0, 0, 0.25);
}

/* Modern, high-visibility tactile push button */
.arcade-btn {
  background: var(--btn);
  color: var(--btnink);
  border-radius: var(--r);
  padding: 12px 28px;
  font-family: var(--f-heading);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-decoration: none;
  text-align: center;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 2px solid transparent;
  transition: transform 0.08s ease, filter 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease;
  user-select: none;
  box-shadow: 0 4px 0 rgba(0,0,0,0.3);
}

.arcade-btn:hover {
  filter: brightness(1.15);
  box-shadow: 0 5px 0 rgba(0,0,0,0.35);
}

.arcade-btn:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 rgba(0,0,0,0.25);
}

.arcade-btn.alt {
  background: transparent;
  color: var(--ink);
  border: 2px solid var(--dim);
  box-shadow: none;
}

.arcade-btn.alt:hover {
  background: var(--fld);
  border-color: var(--ink);
}

/* Target Reticle */
.reticle-cross {
  position: relative;
  width: 50px;
  height: 50px;
  border: 3px solid var(--ink);
  border-radius: 50%;
}
.reticle-cross::before {
  content: "";
  position: absolute;
  left: 22px;
  top: -14px;
  width: 3px;
  height: 78px;
  background: var(--ink);
}
.reticle-cross::after {
  content: "";
  position: absolute;
  top: 22px;
  left: -14px;
  height: 3px;
  width: 78px;
  background: var(--ink);
}

/* Gaze Ring */
.gaze-ring {
  width: 44px;
  height: 44px;
  border: 2px dashed var(--good);
  border-radius: 50%;
  animation: spin-gaze 6s linear infinite;
}

@keyframes spin-gaze {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* Tunnel wall stripes - Pale and clean */
.tunnel-wall {
  background: repeating-linear-gradient(
    135deg,
    var(--dim) 0 12px,
    var(--line) 12px 24px
  );
}

import React from 'react';
import { useArcade, STEP_NAMES, STEP_IDS } from '../../context/ArcadeContext';
import { Check, X } from 'lucide-react';

interface VerticalStepperProps {
  isOpen: boolean;
  onClose: () => void;
}

export const VerticalStepper: React.FC<VerticalStepperProps> = ({ isOpen, onClose }) => {
  const { currentStep, goToStep } = useArcade();

  if (!isOpen) return null;

  return (
    <aside className="w-56 sm:w-64 bg-[var(--body)] border-r-2 border-[var(--bezel)] flex flex-col justify-between p-3 select-none z-30 transition-all duration-200 shadow-xl overflow-y-auto">

      {/* Sidebar Header */}
      <div>
        <div className="flex items-center justify-between border-b border-[var(--line)] pb-2 mb-3">
          <span className="font-heading text-xs tracking-wider text-[var(--ink)] font-bold">
            MISSION STEPS
          </span>
          <button
            onClick={onClose}
            className="p-1 rounded hover:bg-[var(--fld)] text-[var(--dim)] hover:text-[var(--ink)] transition-colors"
            title="Hide Steps Panel"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* 9 Vertical Steps */}
        <div className="space-y-1.5">
          {STEP_NAMES.map((name, idx) => {
            const stepNum = idx + 1;
            const isActive = stepNum === currentStep;
            const isCompleted = stepNum < currentStep;

            return (
              <button
                key={name}
                onClick={() => goToStep(stepNum)}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-left transition-all cursor-pointer ${
                  isActive
                    ? 'bg-[var(--btn)] text-[var(--btnink)] font-bold shadow-md scale-[1.02]'
                    : 'text-[var(--ink)] hover:bg-[var(--fld)] border border-transparent'
                }`}
              >
                {/* Step Circle / Number */}
                <div
                  className={`w-6 h-6 rounded-full flex items-center justify-center font-heading text-xs font-bold transition-colors ${
                    isActive
                      ? 'bg-[var(--good)] text-[var(--on)]'
                      : isCompleted
                      ? 'bg-[var(--line)] text-[var(--ink)]'
                      : 'border border-[var(--dim)] text-[var(--dim)]'
                  }`}
                >
                  {isCompleted ? <Check className="w-3.5 h-3.5" /> : stepNum}
                </div>

                {/* Step Title */}
                <div className="flex-1 min-w-0">
                  <div className={`font-ui text-sm sm:text-base leading-tight truncate ${isActive ? 'font-bold' : 'font-medium'}`}>
                    {name}
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Footer Info */}
      <div className="pt-3 border-t border-[var(--line)] text-xs text-[var(--dim)] font-mono-clean">
        Step {currentStep} of {STEP_NAMES.length} · QNX Lab
      </div>

    </aside>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { useArcade } from '../../context/ArcadeContext';
import { Camera, CameraOff, Eye, Maximize2, Minimize2, Video } from 'lucide-react';

export const CameraFeed: React.FC = () => {
  const { currentStep } = useArcade();
  const videoRef = useRef<HTMLVideoElement>(null);
  const [streamActive, setStreamActive] = useState<boolean>(false);
  const [userMinimized, setUserMinimized] = useState<boolean>(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Auto-minimize during active missions so camera never interferes with games
  const isPlayingGame = currentStep === 6 || currentStep === 7;
  const isMinimized = userMinimized || isPlayingGame;

  useEffect(() => {
    let stream: MediaStream | null = null;

    async function initCamera() {
      try {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
          setErrorMsg('Webcam not supported');
          return;
        }

        stream = await navigator.mediaDevices.getUserMedia({
          video: {
            width: { ideal: 480 },
            height: { ideal: 360 },
            facingMode: 'user',
          },
          audio: false,
        });

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play().catch(() => {});
          setStreamActive(true);
          setErrorMsg(null);
        }
      } catch (err) {
        console.warn('Camera stream error:', err);
        setErrorMsg('Camera offline / permission needed');
        setStreamActive(false);
      }
    }

    initCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(t => t.stop());
      }
    };
  }, []);

  // When minimized during games, show an unobtrusive pill
  if (isMinimized) {
    return (
      <div className="absolute bottom-3 right-3 z-40 select-none">
        <button
          onClick={() => setUserMinimized(!userMinimized)}
          className="flex items-center gap-2 bg-[#0b0f19]/90 hover:bg-[#0b0f19] border border-[var(--dim)] px-3 py-1.5 rounded-full shadow-lg text-xs font-mono-clean text-emerald-400 transition-all cursor-pointer"
          title="Click to expand camera preview"
        >
          <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
          <Video className="w-3.5 h-3.5" />
          <span className="text-slate-200 font-ui font-semibold">CAM 60FPS</span>
          <Maximize2 className="w-3 h-3 text-slate-400" />
        </button>
      </div>
    );
  }

  // Expanded Floating Camera Pop-Up
  return (
    <div className="absolute bottom-4 right-4 z-40 w-64 sm:w-72 bg-[#0b0f19]/95 border-2 border-[var(--dim)] rounded-xl shadow-2xl overflow-hidden flex flex-col select-none transition-all">

      {/* Header */}
      <div className="flex items-center justify-between px-3 py-1.5 bg-[var(--bezel)] text-[var(--scr)] text-xs font-heading font-bold border-b border-black/40">
        <div className="flex items-center gap-2">
          <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
          <span>LIVE QNX CAMERA</span>
        </div>
        <button
          onClick={() => setUserMinimized(true)}
          className="p-1 rounded hover:bg-black/40 text-[var(--scr)] hover:text-white"
          title="Minimize camera"
        >
          <Minimize2 className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Video stream view */}
      <div className="relative aspect-[4/3] bg-black overflow-hidden flex items-center justify-center">
        {streamActive ? (
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            className="w-full h-full object-cover -scale-x-100"
          />
        ) : (
          <div className="flex flex-col items-center justify-center p-4 text-center space-y-1">
            <CameraOff className="w-8 h-8 text-[var(--dim)]" />
            <span className="text-xs font-ui text-[var(--dim)]">
              {errorMsg || 'Starting Camera...'}
            </span>
          </div>
        )}

        {/* Real-time Facial Landmark & Eye-Center Tracking Graphic Overlay */}
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="w-32 h-12 border-2 border-emerald-400/80 rounded flex items-center justify-around px-2">
            <div className="w-3 h-3 rounded-full border border-cyan-400 bg-cyan-400/50 flex items-center justify-center">
              <div className="w-1 h-1 bg-white rounded-full" />
            </div>
            <div className="w-3 h-3 rounded-full border border-cyan-400 bg-cyan-400/50 flex items-center justify-center">
              <div className="w-1 h-1 bg-white rounded-full" />
            </div>
            <span className="absolute -top-3 left-1 text-[9px] font-mono-clean bg-black/80 text-emerald-400 px-1 rounded">
              EYE-LOCK
            </span>
          </div>
        </div>

        {/* Offline Badge */}
        <div className="absolute bottom-2 left-2 flex items-center gap-1.5 text-[10px] font-mono-clean bg-black/80 px-2 py-0.5 rounded text-emerald-400">
          <Eye className="w-3 h-3" />
          <span>100% OFFLINE</span>
        </div>
      </div>

