import React, { useEffect, useState } from 'react';
import { useArcade } from '../../context/ArcadeContext';
import { PixelSprite } from '../common/PixelSprite';
import { playSound } from '../../utils/audio';
import { Play, Shield, Award, CheckCircle } from 'lucide-react';

export const StartScreen: React.FC = () => {
  const { nextStep, goToStep } = useArcade();
  const [selectedMode, setSelectedMode] = useState<'single' | 'operator'>('single');

  // Space / Enter shortcut
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'Enter') {
        e.preventDefault();
        playSound('coin');
        if (selectedMode === 'single') {
          nextStep();
        } else {
          goToStep('operator');
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [nextStep, goToStep, selectedMode]);

  const handleStart = () => {
    playSound('coin');
    if (selectedMode === 'single') {
      nextStep();
    } else {
      goToStep('operator');
    }
  };

  return (
    <div className="flex flex-col h-full justify-between gap-4 p-6 sm:p-8 overflow-y-auto">

      {/* Main 2-Column Layout */}
      <div className="grid md:grid-cols-[1.6fr_1fr] gap-8 flex-1 items-center max-w-5xl mx-auto w-full my-auto">

        {/* Left: Clear, Large Start CTA */}
        <div className="flex flex-col gap-5">
          <div className="space-y-2">
            <span className="font-mono-clean text-sm uppercase tracking-widest text-[var(--good)] font-bold">
              Pediatric Eye-Hand Coordination Lab
            </span>
            <h1 className="font-heading text-3xl sm:text-5xl text-[var(--ink)] font-black tracking-tight leading-none">
              READY, PILOT?
            </h1>
            <p className="font-ui text-lg sm:text-xl text-[var(--dim)] leading-relaxed max-w-lg pt-1">
              Two quick missions to see how smoothly your eyes and hands work together.
            </p>
          </div>

          {/* Mode Selector */}
          <div className="flex flex-col gap-2 font-ui text-lg sm:text-xl">
            <button
              onClick={() => setSelectedMode('single')}
              className={`flex items-center gap-3 px-4 py-2 rounded-lg border-2 text-left cursor-pointer transition-all ${
                selectedMode === 'single'
                  ? 'border-[var(--good)] bg-[var(--fld)] text-[var(--ink)] font-bold'
                  : 'border-transparent text-[var(--dim)] hover:text-[var(--ink)]'
              }`}
            >
              <span className="text-[var(--good)] font-bold">▶</span>
              <span>Singleplayer Screening Run</span>
            </button>

            <button
              onClick={() => setSelectedMode('operator')}
              className={`flex items-center gap-3 px-4 py-2 rounded-lg border-2 text-left cursor-pointer transition-all ${
                selectedMode === 'operator'
                  ? 'border-[var(--good)] bg-[var(--fld)] text-[var(--ink)] font-bold'
                  : 'border-transparent text-[var(--dim)] hover:text-[var(--ink)]'
              }`}
            >
              <span className="text-[var(--good)] font-bold">▶</span>
              <span>Operator &amp; Staff Dashboard</span>
            </button>
          </div>

          {/* Giant Start Button */}
          <div className="pt-2">
            <button
              onClick={handleStart}
              className="arcade-btn text-base sm:text-lg px-8 py-4 flex items-center gap-3 shadow-lg"
            >
              <Play className="w-5 h-5 fill-current" />
              <span>START MISSION [SPACEBAR]</span>
            </button>
          </div>

          {/* Clean Sprite Row */}
          <div className="flex items-center gap-6 pt-2">
            <PixelSprite name="inv" color="var(--good)" size={3.5} />
            <PixelSprite name="sq" color="var(--bad)" size={3.5} />
            <PixelSprite name="ship" color="var(--ink)" size={3.5} />
          </div>
        </div>

        {/* Right: Clean Badges & Hardware Status */}
        <div className="flex flex-col gap-4">

          <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-5 space-y-3 shadow-sm">
            <div className="flex items-center gap-2 font-heading text-sm text-[var(--ink)] font-bold border-b border-[var(--line)] pb-2">
              <Award className="w-4 h-4 text-[var(--good)]" />
