import React, { useState, useEffect, useRef } from 'react';
import { useArcade } from '../../context/ArcadeContext';
import { PixelSprite } from '../common/PixelSprite';
import { playSound } from '../../utils/audio';
import { ArrowRight, Zap, Target } from 'lucide-react';

interface TargetInstance {
  id: number;
  type: 'Round' | 'Square';
  x: number; // percentage (10 to 90)
  y: number; // percentage (15 to 80)
  spawnTime: number;
}

export const Mission1Screen: React.FC = () => {
  const {
    m1Score,
    m1Streak,
    m1GapMs,
    m1Logs,
    recordM1Hit,
    nextStep,
  } = useArcade();

  const [timeLeft, setTimeLeft] = useState(20);
  const [currentTarget, setCurrentTarget] = useState<TargetInstance>({
    id: 1,
    type: 'Round',
    x: 65,
    y: 35,
    spawnTime: Date.now(),
  });
  const [crosshairPos, setCrosshairPos] = useState({ x: 50, y: 50 });
  const [hitToast, setHitToast] = useState<{ text: string; good: boolean } | null>(null);
  const arenaRef = useRef<HTMLDivElement>(null);

  // Timer countdown
  useEffect(() => {
    if (timeLeft <= 0) {
      playSound('win');
      nextStep();
      return;
    }
    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft, nextStep]);

  // Target spawning helper
  const spawnNewTarget = () => {
    const isSquare = Math.random() < 0.28; // 28% decoy
    setCurrentTarget({
      id: Date.now(),
      type: isSquare ? 'Square' : 'Round',
      x: Math.floor(Math.random() * 70 + 15),
      y: Math.floor(Math.random() * 60 + 20),
      spawnTime: Date.now(),
    });
  };

  // User zap handler
  const handleTargetClick = (type: 'Round' | 'Square') => {
    const elapsed = Date.now() - currentTarget.spawnTime;
    const simulatedGap = Math.max(160, Math.min(360, elapsed - 40 + Math.floor(Math.random() * 25)));

    recordM1Hit(type, simulatedGap);

    if (type === 'Round') {
      setHitToast({ text: `ZAP! +${100 * Math.max(1, m1Streak)} (${simulatedGap}ms)`, good: true });
    } else {
      setHitToast({ text: 'DECOY TRICK! -50 (Impulse Error)', good: false });
    }

    setTimeout(() => setHitToast(null), 800);
    spawnNewTarget();
  };

  // Crosshair tracking on mouse move
  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!arenaRef.current) return;
    const rect = arenaRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    setCrosshairPos({
      x: Math.max(4, Math.min(96, x)),
      y: Math.max(4, Math.min(96, y)),
    });
  };

  // Keyboard Spacebar fires at crosshair location
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space') {
        e.preventDefault();
        const dx = Math.abs(crosshairPos.x - currentTarget.x);
        const dy = Math.abs(crosshairPos.y - currentTarget.y);
        if (dx < 20 && dy < 20) {
          handleTargetClick(currentTarget.type);
        } else {
          playSound('laser');
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [crosshairPos, currentTarget]);

  return (
    <div className="flex flex-col h-full w-full justify-between gap-1 p-2 sm:p-3 overflow-hidden select-none">

      {/* Top Stats HUD (Gap ms, Time, Score, Streak) */}
      <div className="grid grid-cols-4 gap-2 px-1">
        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2 text-center shadow-sm">
          <span className="font-ui text-xs font-bold text-[var(--dim)] uppercase block">Reaction Gap</span>
          <div className="font-heading text-xl sm:text-2xl text-[var(--good)] font-black">
            {m1GapMs} ms
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2 text-center shadow-sm">
          <span className="font-ui text-xs font-bold text-[var(--dim)] uppercase block">Time Remaining</span>
          <div className="font-heading text-xl sm:text-2xl text-[var(--ink)] font-black">
            0:{timeLeft.toString().padStart(2, '0')}
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2 text-center shadow-sm">
          <span className="font-ui text-xs font-bold text-[var(--dim)] uppercase block">Score</span>
          <div className="font-heading text-xl sm:text-2xl text-[var(--good)] font-black">
            {m1Score}
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2 text-center shadow-sm">
          <span className="font-ui text-xs font-bold text-[var(--dim)] uppercase block">Streak Multiplier</span>
          <div className="font-heading text-xl sm:text-2xl text-[var(--btn)] font-black">
            ×{m1Streak}
          </div>
        </div>
      </div>

      {/* Main Game Area: MASSIVE Arena with a COMPACT Live Log on the right */}
      <div className="grid grid-cols-[1fr_220px] sm:grid-cols-[1fr_250px] gap-2 flex-1 items-stretch my-1 min-h-0">

        {/* HUGE Main Target Arena */}
        <div className="flex flex-col gap-1 min-h-0">

          {/* Target rule chips */}
          <div className="flex items-center gap-2 font-ui text-xs font-bold">
            <span className="bg-[var(--good)] text-white px-3 py-1 rounded-full uppercase shadow-sm">
              Zap round target
            </span>
            <span className="bg-[var(--bad)] text-white px-3 py-1 rounded-full uppercase shadow-sm">
              Skip square decoy
            </span>
            <span className="text-[var(--dim)] ml-auto text-xs hidden sm:inline font-semibold">
              Click target or press [SPACEBAR] to fire
            </span>
          </div>

          {/* Interactive Arena */}
          <div
            ref={arenaRef}
            onMouseMove={handleMouseMove}
            className="relative flex-1 rounded-2xl border-3 border-[var(--dim)] bg-[var(--fld)] overflow-hidden shadow-inner cursor-crosshair min-h-0"
          >
            {/* Hit Feedback Toast */}
            {hitToast && (
              <div className="absolute top-4 inset-x-0 flex justify-center z-30 pointer-events-none">
                <span className={`font-heading text-sm sm:text-base font-bold px-5 py-2 rounded-full border-2 shadow-2xl ${
                  hitToast.good
                    ? 'bg-[var(--good)] text-white border-white animate-bounce'
                    : 'bg-[var(--bad)] text-white border-white animate-pulse'
                }`}>
                  {hitToast.text}
                </span>
              </div>
            )}

            {/* Active Large Target Instance */}
            <div
              style={{ left: `${currentTarget.x}%`, top: `${currentTarget.y}%` }}
              onClick={() => handleTargetClick(currentTarget.type)}
              className="absolute -translate-x-1/2 -translate-y-1/2 cursor-pointer z-20 group"
            >
              <div className="relative p-3 flex items-center justify-center">
                {/* Simulated Gaze Lock Ring around target */}
                <div className="absolute -inset-2 gaze-ring opacity-75 pointer-events-none" />

                {currentTarget.type === 'Round' ? (
                  <PixelSprite
                    name="inv"
                    color="var(--good)"
                    size={6}
                    className="group-hover:scale-110 transition-transform drop-shadow-xl"
                  />
                ) : (
                  <PixelSprite
                    name="sq"
                    color="var(--bad)"
                    size={6}
                    className="group-hover:scale-110 transition-transform drop-shadow-xl animate-pulse"
                  />
                )}
              </div>
            </div>

            {/* Big Crosshair following pointer */}
            <div
              style={{ left: `${crosshairPos.x}%`, top: `${crosshairPos.y}%` }}
              className="absolute -translate-x-1/2 -translate-y-1/2 pointer-events-none z-15"
            >
              <div className="reticle-cross opacity-85" />
            </div>

          </div>
        </div>

        {/* COMPACT Right Live Log */}
        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-3 flex flex-col justify-between overflow-hidden shadow-sm">
          <div className="min-h-0 flex-1 flex flex-col">
            <div className="font-heading text-xs uppercase tracking-wider text-[var(--ink)] font-bold border-b border-[var(--line)] pb-1.5 mb-2">
              Live QNX Log
            </div>

            <div className="space-y-1.5 font-ui text-sm overflow-y-auto pr-1 flex-1">
              {m1Logs.slice(0, 8).map((log) => (
                <div
                  key={log.id}
                  className="flex items-center justify-between border-b border-[var(--line)] pb-1"
                >
                  <span className="text-[var(--ink)] font-medium truncate">{log.label}</span>
                  <b className={`font-bold ${log.success ? 'text-[var(--good)]' : 'text-[var(--bad)]'}`}>
                    {log.text}
                  </b>
                </div>
              ))}
            </div>
          </div>

          <div className="pt-2 border-t border-[var(--line)]">
            <button
              onClick={nextStep}
              className="arcade-btn glow-guide text-xs py-2.5 w-full flex items-center justify-center gap-1.5"
            >
              <span>Next Mission</span>
              <ArrowRight className="w-4 h-4" />
            </button>
          </div>
        </div>

      </div>

      {/* Slim Bottom Status */}
      <div className="flex items-center justify-between px-2 text-xs font-ui text-[var(--dim)] font-semibold">
        <span>QNX RTOS Clock Active · Video Offline</span>
        <span>Target Lock Mission (1 of 2)</span>
      </div>

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useArcade } from '../../context/ArcadeContext';
import { PixelSprite } from '../common/PixelSprite';
import { playSound } from '../../utils/audio';
import { ArrowRight } from 'lucide-react';

export const Mission2Screen: React.FC = () => {
  const {
    m2Steady,
    m2OnPath,
    m2EyesOnComet,
    m2TremorPoints,
    m2CatchUpJumps,
    updateM2Tremor,
    nextStep,
  } = useArcade();

  const [timeLeft, setTimeLeft] = useState(25);
  const [cometX, setCometX] = useState(20);
  const [shipY, setShipY] = useState(50); // percentage 22 to 78
  const [cometDirection, setCometDirection] = useState(1);

  // Timer & Comet motion loop
  useEffect(() => {
    if (timeLeft <= 0) {
      playSound('win');
      nextStep();
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);

      // Smoothly advance comet back and forth
      setCometX(prev => {
        let next = prev + 5 * cometDirection;
        if (next > 82) {
          setCometDirection(-1);
          next = 82;
        } else if (next < 18) {
          setCometDirection(1);
          next = 18;
        }
        return next;
      });

      // Sample micro-tremor variance & corridor accuracy
      const inCorridor = shipY >= 26 && shipY <= 74;
      const noise = inCorridor ? Math.random() * 5 + 8 : Math.random() * 14 + 10;
      const eyeSmooth = Math.random() > 0.15;
      updateM2Tremor(noise, inCorridor, eyeSmooth);
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft, cometDirection, shipY, updateM2Tremor, nextStep]);

  // Steer ship with keys
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowUp' || e.key === 'w' || e.key === 'W') {
        e.preventDefault();
        setShipY(prev => Math.max(22, prev - 6));
      } else if (e.key === 'ArrowDown' || e.key === 's' || e.key === 'S') {
        e.preventDefault();
        setShipY(prev => Math.min(78, prev + 6));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Build SVG sparkline polyline points string from m2TremorPoints
  const sparklinePoints = m2TremorPoints
    .map((val, idx) => {
      const x = (idx / (m2TremorPoints.length - 1)) * 100;
      const y = Math.max(2, Math.min(22, 24 - val));
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(' ');

  return (
    <div className="flex flex-col h-full w-full justify-between gap-1 p-2 sm:p-3 overflow-hidden select-none">

      {/* Top Stats HUD (Time, Steady, On path, Eyes on comet) */}
      <div className="grid grid-cols-4 gap-2 px-1">
        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2 text-center shadow-sm">
          <span className="font-ui text-xs font-bold text-[var(--dim)] uppercase block">Time Remaining</span>
          <div className="font-heading text-xl sm:text-2xl text-[var(--ink)] font-black">
            0:{timeLeft.toString().padStart(2, '0')}
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2 text-center shadow-sm">
          <span className="font-ui text-xs font-bold text-[var(--dim)] uppercase block">Motor Steadiness</span>
          <div className="font-heading text-xl sm:text-2xl text-[var(--good)] font-black">
            {Math.round(m2Steady)}%
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2 text-center shadow-sm">
          <span className="font-ui text-xs font-bold text-[var(--dim)] uppercase block">Path Accuracy</span>
          <div className="font-heading text-xl sm:text-2xl text-[var(--ink)] font-black">
            {Math.round(m2OnPath)}%
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2 text-center shadow-sm">
          <span className="font-ui text-xs font-bold text-[var(--dim)] uppercase block">Eyes on Comet</span>
          <div className="font-heading text-xl sm:text-2xl text-[var(--good)] font-black">
            {Math.round(m2EyesOnComet)}%
          </div>
        </div>
      </div>

      {/* Main Game Area: MASSIVE Tunnel with COMPACT Tremor Gauge on the right */}
      <div className="grid grid-cols-[1fr_220px] sm:grid-cols-[1fr_250px] gap-2 flex-1 items-stretch my-1 min-h-0">

        {/* HUGE Main Asteroid Tunnel */}
        <div className="flex flex-col gap-1 min-h-0">

          <div className="flex items-center gap-2 font-ui text-xs font-bold">
            <span className="bg-[var(--good)] text-white px-3 py-1 rounded-full uppercase shadow-sm">
              Eyes locked on comet
            </span>
            <span className="bg-[var(--btn)] text-white px-3 py-1 rounded-full uppercase shadow-sm">
              Steer ship with [W/S] or [↑/↓]
            </span>
            <span className="text-[var(--dim)] ml-auto text-xs hidden sm:inline font-semibold">
              Avoid corridor borders to keep score high
            </span>
          </div>

          {/* Interactive Tunnel Field */}
          <div className="relative flex-1 rounded-2xl border-3 border-[var(--dim)] bg-[var(--fld)] overflow-hidden shadow-inner min-h-0">

            {/* Pale Upper Wall */}
            <div className="tunnel-wall absolute top-0 inset-x-0 h-[20%] border-b-2 border-[var(--dim)] opacity-40" />

            {/* Pale Lower Wall */}
            <div className="tunnel-wall absolute bottom-0 inset-x-0 h-[20%] border-t-2 border-[var(--dim)] opacity-40" />

            {/* Center Dashed Line */}
            <div className="absolute inset-x-0 top-1/2 border-t-2 border-dashed border-[var(--line)] opacity-40 pointer-events-none" />

            {/* Smooth Pursuit Comet with Tail */}
            <div
              style={{ left: `${cometX}%`, top: '35%' }}
