      {/* Slim Bottom Status */}
      <div className="flex items-center justify-between px-2 text-xs font-ui text-[var(--dim)] font-semibold">
        <span>Smooth Pursuit &amp; Tremor Telemetry Active</span>
        <span>Asteroid Tunnel Mission (2 of 2)</span>
      </div>

    </div>
  );
};

