  width: 48px;
  height: 48px;
  border: 3px solid var(--ink);
  border-radius: 50%;
  box-shadow: 0 0 10px rgba(0,0,0,0.2);
}
.reticle-cross::before {
  content: "";
  position: absolute;
  left: 21px;
  top: -14px;
  width: 3px;
  height: 76px;
