    var(--dim) 0 14px,
    var(--line) 14px 28px
  );
}

import React, { createContext, useContext, useRef, useState, useEffect, useCallback } from 'react';
import { playSound } from '../utils/audio';

declare global {
  interface Navigator {
    serial?: {
      requestPort: (options?: unknown) => Promise<SerialPort>;
      getPorts: () => Promise<SerialPort[]>;
    };
  }

  interface SerialPort {
    open: (options: { baudRate: number }) => Promise<void>;
    close: () => Promise<void>;
    readable: ReadableStream<Uint8Array>;
    writable: WritableStream<Uint8Array>;
  }
}

export interface JoystickData {
  jx: number;
  jy: number;
  btn: boolean;
}

interface JoystickContextType {
  isConnected: boolean;
  isSupported: boolean;
  joystickData: JoystickData;
  joystickRef: React.MutableRefObject<JoystickData>;
  normalizeAxis: (val: number) => number;
  connectJoystick: () => Promise<void>;
  disconnectJoystick: () => Promise<void>;
  errorMsg: string | null;
}

const JoystickContext = createContext<JoystickContextType | undefined>(undefined);

export const JoystickProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const joystickRef = useRef<JoystickData>({ jx: 512, jy: 512, btn: false });
  const [joystickData, setJoystickData] = useState<JoystickData>({ jx: 512, jy: 512, btn: false });
  const [isConnected, setIsConnected] = useState<boolean>(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const portRef = useRef<SerialPort | null>(null);
  const readerRef = useRef<ReadableStreamDefaultReader<string> | null>(null);
  const keepReadingRef = useRef<boolean>(false);

  const isSupported = typeof navigator !== 'undefined' && 'serial' in navigator;

  // Helper: Normalize 0-1023 to -1..1 with deadzone
  const normalizeAxis = useCallback((val: number): number => {
    const centered = val - 512;
    if (Math.abs(centered) < 35) return 0;
    return Math.max(-1, Math.min(1, centered / 512));
  }, []);

  // Sync joystickRef to React state at ~15Hz for UI badges (without slowing down 60fps game loop)
  useEffect(() => {
    const interval = setInterval(() => {
      setJoystickData({ ...joystickRef.current });
    }, 66);
    return () => clearInterval(interval);
  }, []);

  // Web Serial Connection
  const connectJoystick = async () => {
    if (!navigator.serial) {
      setErrorMsg('Web Serial API is not supported in this browser. Use Chrome or Edge.');
      return;
    }

    try {
      setErrorMsg(null);
      const port = await navigator.serial.requestPort();
      await port.open({ baudRate: 115200 });

      portRef.current = port;
      setIsConnected(true);
      keepReadingRef.current = true;
      playSound('coin');

      const textDecoder = new TextDecoderStream();
      port.readable.pipeTo(textDecoder.writable);
      const reader = textDecoder.readable.getReader();
      readerRef.current = reader;

      let buffer = '';

      while (keepReadingRef.current) {
        const { value, done } = await reader.read();
        if (done) break;

        buffer += value;
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          const trimmed = line.trim();
          if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
            try {
              const data = JSON.parse(trimmed);
              if (typeof data.jx === 'number' && typeof data.jy === 'number') {
                joystickRef.current = {
                  jx: data.jx,
                  jy: data.jy,
                  btn: Boolean(data.btn),
                };
              }
            } catch {
              // Ignore partial packet line
            }
          }
        }
      }
    } catch (err: unknown) {
      console.warn('Serial connection cancelled or failed:', err);
      setIsConnected(false);
      setErrorMsg((err as Error)?.message || 'Failed to connect Arduino serial');
    }
  };

  const disconnectJoystick = async () => {
    keepReadingRef.current = false;
    try {
      if (readerRef.current) {
        await readerRef.current.cancel();
        readerRef.current = null;
      }
      if (portRef.current) {
        await portRef.current.close();
        portRef.current = null;
      }
    } catch (e) {
      console.warn('Disconnect error:', e);
    }
    setIsConnected(false);
    joystickRef.current = { jx: 512, jy: 512, btn: false };
  };

  // Keyboard simulator fallback: arrow keys / WASD modify joystickRef if physical Arduino is not connected
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isConnected) return; // Physical Arduino takes precedence
      if (e.key === 'ArrowLeft' || e.key === 'a') joystickRef.current.jx = 100;
      if (e.key === 'ArrowRight' || e.key === 'd') joystickRef.current.jx = 924;
      if (e.key === 'ArrowUp' || e.key === 'w') joystickRef.current.jy = 100;
      if (e.key === 'ArrowDown' || e.key === 's') joystickRef.current.jy = 924;
      if (e.key === ' ' || e.key === 'Enter') joystickRef.current.btn = true;
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      if (isConnected) return;
      if (['ArrowLeft', 'ArrowRight', 'a', 'd'].includes(e.key)) joystickRef.current.jx = 512;
      if (['ArrowUp', 'ArrowDown', 'w', 's'].includes(e.key)) joystickRef.current.jy = 512;
      if ([' ', 'Enter'].includes(e.key)) joystickRef.current.btn = false;
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [isConnected]);

  return (
    <JoystickContext.Provider
      value={{
        isConnected,
        isSupported,
        joystickData,
        joystickRef,
        normalizeAxis,
        connectJoystick,
        disconnectJoystick,
        errorMsg,
      }}
    >
      {children}
    </JoystickContext.Provider>
  );
};

export const useJoystick = () => {
  const context = useContext(JoystickContext);
  if (!context) {
    throw new Error('useJoystick must be used within a JoystickProvider');
  }
  return context;
};

