    y: 200,
    isSquare: false,
    spawnTime: performance.now(),
    radius: 30,
  });

  const [timeLeft, setTimeLeft] = useState<number>(20);
  const [hitToast, setHitToast] = useState<{ text: string; good: boolean } | null>(null);

  // 20-second countdown
  useEffect(() => {
    if (timeLeft <= 0) {
      playSound('win');
      nextStep();
      return;
    }
    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft, nextStep]);

  // Spawn new target helper
  const spawnTarget = (width: number, height: number) => {
    const isSquare = Math.random() < 0.28;
    targetRef.current = {
      x: 70 + Math.random() * (width - 140),
      y: 70 + Math.random() * (height - 140),
      isSquare,
      spawnTime: performance.now(),
      radius: 30,
    };
  };

  // 60FPS ARDUINO JOYSTICK + CANVAS GAME LOOP
  useEffect(() => {
    let animId: number;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Resize canvas to match display size
    const updateCanvasSize = () => {
      const rect = canvas.getBoundingClientRect();
      if (canvas.width !== rect.width || canvas.height !== rect.height) {
        canvas.width = rect.width;
        canvas.height = rect.height;
        if (targetRef.current.x > rect.width || targetRef.current.y > rect.height) {
          spawnTarget(rect.width, rect.height);
        }
      }
    };
    updateCanvasSize();
    window.addEventListener('resize', updateCanvasSize);

    const loop = () => {
      const { jx, jy, btn } = joystickRef.current;
      const vx = normalizeAxis(jx);
      const vy = normalizeAxis(jy);

      // Move crosshair smoothly via Arduino Joystick analog axes (speed: * 8.5)
      crosshairRef.current.x = Math.max(
        25,
        Math.min(canvas.width - 25, crosshairRef.current.x + vx * 8.5)
      );
      crosshairRef.current.y = Math.max(
        25,
        Math.min(canvas.height - 25, crosshairRef.current.y + vy * 8.5)
      );

      // Detect Arduino button click (rising edge: false -> true)
      if (btn && !prevBtnRef.current) {
        const dist = Math.hypot(
          crosshairRef.current.x - targetRef.current.x,
          crosshairRef.current.y - targetRef.current.y
        );

        // Hit detection (target radius 30 + crosshair radius 18 = 48)
        if (dist < 48) {
          const reactionTime = Math.round(performance.now() - targetRef.current.spawnTime);
          if (targetRef.current.isSquare) {
            // Decoy error
            recordM1Hit('Square', reactionTime);
            setHitToast({ text: 'DECOY TRICK! -50 (Impulse Error)', good: false });
          } else {
            // Round alien hit
            recordM1Hit('Round', reactionTime);
            setHitToast({ text: `HIT! ${reactionTime} ms`, good: true });
          }
          setTimeout(() => setHitToast(null), 900);
          spawnTarget(canvas.width, canvas.height);
        } else {
          // Missed click
          playSound('laser');
        }
      }
      prevBtnRef.current = btn;

      // Render Retro Arcade Canvas Arena
      ctx.fillStyle = '#070b16';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Pale radar grid lines
      ctx.strokeStyle = 'rgba(71, 85, 105, 0.25)';
      ctx.lineWidth = 1;
      const step = 40;
      for (let x = 0; x < canvas.width; x += step) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
      }
      for (let y = 0; y < canvas.height; y += step) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      // Draw Target (Round Alien = Green, Square Decoy = Red)
      const target = targetRef.current;
      if (target.isSquare) {
        // Square Alien Decoy (ADHD impulse test)
        ctx.fillStyle = '#f43f5e';
        ctx.shadowColor = '#f43f5e';
        ctx.shadowBlur = 18;
        ctx.fillRect(target.x - target.radius, target.y - target.radius, target.radius * 2, target.radius * 2);

        // Decoy label
        ctx.fillStyle = '#ffffff';
        ctx.font = '10px "Press Start 2P", monospace';
        ctx.textAlign = 'center';
        ctx.fillText('DECOY', target.x, target.y + 4);
      } else {
        // Round Alien Zap Target
        ctx.fillStyle = '#10b981';
        ctx.shadowColor = '#10b981';
        ctx.shadowBlur = 22;
        ctx.beginPath();
        ctx.arc(target.x, target.y, target.radius, 0, Math.PI * 2);
        ctx.fill();

        // Pulsing radar ring
        ctx.strokeStyle = '#00f5ff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(target.x, target.y, target.radius + 8, 0, Math.PI * 2);
        ctx.stroke();

        ctx.fillStyle = '#0f172a';
        ctx.font = '10px "Press Start 2P", monospace';
        ctx.textAlign = 'center';
        ctx.fillText('ZAP', target.x, target.y + 4);
      }
      ctx.shadowBlur = 0;

      // Draw Player Crosshair (turns yellow when joystick button is held!)
      const ch = crosshairRef.current;
      ctx.strokeStyle = btn ? '#facc15' : '#38bdf8';
      ctx.lineWidth = 3;

      ctx.beginPath();
      ctx.arc(ch.x, ch.y, 18, 0, Math.PI * 2);
      ctx.stroke();

      // Crosshair center lines
      ctx.beginPath();
      ctx.moveTo(ch.x - 26, ch.y);
      ctx.lineTo(ch.x + 26, ch.y);
      ctx.moveTo(ch.x, ch.y - 26);
      ctx.lineTo(ch.x, ch.y + 26);
      ctx.stroke();

      animId = requestAnimationFrame(loop);
    };

    animId = requestAnimationFrame(loop);
    return () => {
      cancelAnimationFrame(animId);
      window.removeEventListener('resize', updateCanvasSize);
    };
  }, [normalizeAxis, recordM1Hit]);

  // Mouse move backup on canvas
  const handleCanvasMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isConnected) return; // Physical Arduino controls position
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    crosshairRef.current.x = e.clientX - rect.left;
    crosshairRef.current.y = e.clientY - rect.top;
  };

  const handleCanvasClick = () => {
    if (isConnected) return; // Physical Arduino button clicks
    joystickRef.current.btn = true;
    setTimeout(() => {
      joystickRef.current.btn = false;
    }, 50);
  };

  return (
    <div className="flex flex-col h-full w-full justify-between gap-1 p-2 sm:p-3 overflow-hidden select-none">

      {/* Top Arcade HUD Stats */}
      <div className="grid grid-cols-4 gap-2 px-1">
        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-lg p-2 text-center shadow-sm">
          <span className="font-pixel text-[9px] text-[var(--dim)] uppercase block">Reaction Gap</span>
          <div className="font-pixel text-sm sm:text-base text-[var(--good)] font-bold mt-1">
            {m1GapMs} ms
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-lg p-2 text-center shadow-sm">
          <span className="font-pixel text-[9px] text-[var(--dim)] uppercase block">Time Remaining</span>
          <div className="font-pixel text-sm sm:text-base text-[var(--ink)] font-bold mt-1">
            0:{timeLeft.toString().padStart(2, '0')}
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-lg p-2 text-center shadow-sm">
          <span className="font-pixel text-[9px] text-[var(--dim)] uppercase block">Score</span>
          <div className="font-pixel text-sm sm:text-base text-[var(--good)] font-bold mt-1">
            {m1Score}
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-lg p-2 text-center shadow-sm">
          <span className="font-pixel text-[9px] text-[var(--dim)] uppercase block">Streak</span>
          <div className="font-pixel text-sm sm:text-base text-[var(--btn)] font-bold mt-1">
            ×{m1Streak}
          </div>
        </div>
      </div>

      {/* Main Game Area: MASSIVE Canvas Arena + COMPACT Live Log */}
      <div className="grid grid-cols-[1fr_210px] sm:grid-cols-[1fr_240px] gap-2 flex-1 items-stretch my-1 min-h-0">

        {/* HUGE 60FPS Canvas Arena */}
        <div className="flex flex-col gap-1 min-h-0">

          <div className="flex items-center gap-2 font-pixel text-[10px]">
            <span className="bg-[#10b981] text-black px-2.5 py-1 rounded uppercase font-bold">
              Zap Green Round
            </span>
            <span className="bg-[#f43f5e] text-white px-2.5 py-1 rounded uppercase font-bold">
              Skip Red Square
            </span>

            {/* Arduino Status Indicator */}
            {isConnected ? (
              <span className="ml-auto flex items-center gap-1.5 text-emerald-400 font-terminal text-sm">
                <Gamepad2 className="w-4 h-4" /> Arduino Joystick Active
              </span>
            ) : (
              <button
                onClick={connectJoystick}
                className="ml-auto text-amber-300 hover:text-amber-200 underline font-terminal text-sm cursor-pointer"
              >
                + Connect Arduino Joystick (115200)
              </button>
            )}
          </div>

          {/* 60FPS Canvas Element */}
          <div className="relative flex-1 rounded-xl border-3 border-[var(--dim)] overflow-hidden shadow-inner min-h-0">
            {hitToast && (
              <div className="absolute top-4 inset-x-0 flex justify-center z-30 pointer-events-none">
                <span className={`font-pixel text-xs px-4 py-2 rounded-lg border-2 shadow-2xl ${
                  hitToast.good
                    ? 'bg-[#10b981] text-black border-white animate-bounce'
                    : 'bg-[#f43f5e] text-white border-white animate-pulse'
                }`}>
                  {hitToast.text}
                </span>
              </div>
            )}

            <canvas
              ref={canvasRef}
              onMouseMove={handleCanvasMouseMove}
              onClick={handleCanvasClick}
              className="w-full h-full block cursor-crosshair"
            />
          </div>
        </div>

        {/* Compact Right Live Log */}
        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2.5 flex flex-col justify-between overflow-hidden shadow-sm">
          <div className="min-h-0 flex-1 flex flex-col">
            <div className="font-pixel text-[10px] uppercase text-[var(--ink)] font-bold border-b border-[var(--line)] pb-1.5 mb-2">
              QNX Live Log
            </div>

            <div className="space-y-1 font-terminal text-base overflow-y-auto pr-1 flex-1">
              {m1Logs.slice(0, 8).map((log) => (
                <div
                  key={log.id}
                  className="flex items-center justify-between border-b border-[var(--line)] pb-0.5"
                >
                  <span className="text-[var(--ink)] truncate">{log.label}</span>
                  <b className={`font-bold ${log.success ? 'text-[var(--good)]' : 'text-[var(--bad)]'}`}>
                    {log.text}
                  </b>
                </div>
              ))}
            </div>
          </div>

          <div className="pt-2 border-t border-[var(--line)]">
            <button
              onClick={nextStep}
              className="arcade-btn glow-guide text-[10px] py-2 w-full flex items-center justify-center gap-1.5"
            >
              <span>Next Mission</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>

      </div>

      {/* Slim Bottom Status */}
      <div className="flex items-center justify-between px-2 text-xs font-terminal text-[var(--dim)]">
        <span>QNX RTOS Clock · Deterministic Sub-200ms Telemetry</span>
        <span>Mission 1 of 2</span>
      </div>

    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { useArcade } from '../../context/ArcadeContext';
import { useJoystick } from '../../context/JoystickContext';
import { PixelSprite } from '../common/PixelSprite';
import { playSound } from '../../utils/audio';
import { ArrowRight, Gamepad2 } from 'lucide-react';

export const Mission2Screen: React.FC = () => {
  const {
    m2Steady,
    m2OnPath,
    m2EyesOnComet,
    m2TremorPoints,
    m2CatchUpJumps,
    updateM2Tremor,
    nextStep,
  } = useArcade();

  const { joystickRef, normalizeAxis, isConnected, connectJoystick } = useJoystick();

  const [timeLeft, setTimeLeft] = useState<number>(25);
  const [cometX, setCometX] = useState<number>(20);
  const [shipY, setShipY] = useState<number>(50); // percentage 22 to 78
  const [cometDirection, setCometDirection] = useState<number>(1);

  const prevJoyRef = useRef<{ jx: number; jy: number }>({ jx: 512, jy: 512 });

  // 60FPS loop for steering spaceship with Arduino Joystick
  useEffect(() => {
    let animId: number;

    const loop = () => {
      const { jx, jy } = joystickRef.current;
      const vy = normalizeAxis(jy);

      // If joystick is tilted, steer ship smoothly
      if (Math.abs(vy) > 0.05) {
        setShipY(prev => Math.max(22, Math.min(78, prev + vy * 1.5)));
      }

      animId = requestAnimationFrame(loop);
    };

    animId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animId);
  }, [normalizeAxis]);

  // Timer, Comet motion & Real Hardware Tremor loop
  useEffect(() => {
    if (timeLeft <= 0) {
      playSound('win');
      nextStep();
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);

      // Smoothly advance comet back and forth
      setCometX(prev => {
        let next = prev + 5 * cometDirection;
        if (next > 82) {
          setCometDirection(-1);
          next = 82;
        } else if (next < 18) {
          setCometDirection(1);
          next = 18;
        }
        return next;
      });

      // Sample real micro-tremor variance from Arduino joystick reads
      const { jx, jy } = joystickRef.current;
      const dx = Math.abs(jx - prevJoyRef.current.jx);
      const dy = Math.abs(jy - prevJoyRef.current.jy);
      prevJoyRef.current = { jx, jy };

      const inCorridor = shipY >= 26 && shipY <= 74;
      const noise = isConnected
        ? Math.max(4, Math.min(22, (dx + dy) / 4 + (inCorridor ? 6 : 14)))
        : (inCorridor ? Math.random() * 5 + 8 : Math.random() * 14 + 10);

      const eyeSmooth = Math.random() > 0.15;
      updateM2Tremor(noise, inCorridor, eyeSmooth);
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft, cometDirection, shipY, updateM2Tremor, nextStep, isConnected]);

  // Steer ship with keys as backup
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowUp' || e.key === 'w' || e.key === 'W') {
        e.preventDefault();
        setShipY(prev => Math.max(22, prev - 6));
      } else if (e.key === 'ArrowDown' || e.key === 's' || e.key === 'S') {
        e.preventDefault();
        setShipY(prev => Math.min(78, prev + 6));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Build SVG sparkline polyline points string from m2TremorPoints
  const sparklinePoints = m2TremorPoints
    .map((val, idx) => {
      const x = (idx / (m2TremorPoints.length - 1)) * 100;
      const y = Math.max(2, Math.min(22, 24 - val));
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(' ');

  return (
    <div className="flex flex-col h-full w-full justify-between gap-1 p-2 sm:p-3 overflow-hidden select-none">

      {/* Top Stats HUD (Time, Steady, On path, Eyes on comet) */}
      <div className="grid grid-cols-4 gap-2 px-1">
        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-lg p-2 text-center shadow-sm">
          <span className="font-pixel text-[9px] text-[var(--dim)] uppercase block">Time Remaining</span>
          <div className="font-pixel text-sm sm:text-base text-[var(--ink)] font-bold mt-1">
            0:{timeLeft.toString().padStart(2, '0')}
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-lg p-2 text-center shadow-sm">
          <span className="font-pixel text-[9px] text-[var(--dim)] uppercase block">Motor Steadiness</span>
          <div className="font-pixel text-sm sm:text-base text-[var(--good)] font-bold mt-1">
            {Math.round(m2Steady)}%
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-lg p-2 text-center shadow-sm">
          <span className="font-pixel text-[9px] text-[var(--dim)] uppercase block">Path Accuracy</span>
          <div className="font-pixel text-sm sm:text-base text-[var(--ink)] font-bold mt-1">
            {Math.round(m2OnPath)}%
          </div>
        </div>

        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-lg p-2 text-center shadow-sm">
          <span className="font-pixel text-[9px] text-[var(--dim)] uppercase block">Eyes on Comet</span>
          <div className="font-pixel text-sm sm:text-base text-[var(--good)] font-bold mt-1">
            {Math.round(m2EyesOnComet)}%
          </div>
        </div>
      </div>

      {/* Main Game Area: MASSIVE Tunnel + COMPACT Tremor Gauge on the right */}
      <div className="grid grid-cols-[1fr_210px] sm:grid-cols-[1fr_240px] gap-2 flex-1 items-stretch my-1 min-h-0">

        {/* HUGE Main Asteroid Tunnel */}
        <div className="flex flex-col gap-1 min-h-0">

          <div className="flex items-center gap-2 font-pixel text-[10px]">
            <span className="bg-[#10b981] text-black px-2.5 py-1 rounded uppercase font-bold">
              Eyes on comet
            </span>
            <span className="bg-[var(--btn)] text-white px-2.5 py-1 rounded uppercase font-bold">
              {isConnected ? 'Steer with Arduino Stick' : 'Steer with [W/S] or [↑/↓]'}
            </span>

            {isConnected ? (
              <span className="ml-auto flex items-center gap-1.5 text-emerald-400 font-terminal text-sm">
                <Gamepad2 className="w-4 h-4" /> Arduino Active
              </span>
            ) : (
              <button
                onClick={connectJoystick}
                className="ml-auto text-amber-300 hover:text-amber-200 underline font-terminal text-sm cursor-pointer"
              >
                + Connect Arduino
              </button>
            )}
          </div>

          {/* Interactive Tunnel Field */}
          <div className="relative flex-1 rounded-xl border-3 border-[var(--dim)] bg-[var(--fld)] overflow-hidden shadow-inner min-h-0">

            {/* Pale Upper Wall */}
            <div className="tunnel-wall absolute top-0 inset-x-0 h-[20%] border-b-2 border-[var(--dim)] opacity-40" />

            {/* Pale Lower Wall */}
            <div className="tunnel-wall absolute bottom-0 inset-x-0 h-[20%] border-t-2 border-[var(--dim)] opacity-40" />

            {/* Center Dashed Line */}
            <div className="absolute inset-x-0 top-1/2 border-t-2 border-dashed border-[var(--line)] opacity-40 pointer-events-none" />

            {/* Smooth Pursuit Comet with Tail */}
            <div
              style={{ left: `${cometX}%`, top: '35%' }}
              className="absolute -translate-x-1/2 -translate-y-1/2 transition-all duration-700 pointer-events-none z-20"
            >
              <div className="relative flex items-center">
                <div className="w-24 sm:w-36 h-3 bg-gradient-to-l from-[var(--good)] to-transparent opacity-85 rounded-full" />

                <div className="relative w-9 h-9 rounded-full bg-[var(--good)] shadow-[0_0_25px_var(--good)] flex items-center justify-center animate-pulse">
                  <div className="absolute -inset-2 gaze-ring opacity-80" />
                  <div className="w-2.5 h-2.5 rounded-full bg-white shadow" />
                </div>
              </div>

              <span className="absolute top-full mt-1.5 left-1/2 -translate-x-1/2 font-pixel text-[8px] text-white bg-black/70 px-2 py-0.5 rounded whitespace-nowrap shadow">
                GAZE TARGET
              </span>
            </div>

            {/* Player Spaceship */}
            <div
              style={{ left: '18%', top: `${shipY}%` }}
              className="absolute -translate-x-1/2 -translate-y-1/2 transition-all duration-150 z-20"
            >
              <div className="relative drop-shadow-xl">
                <PixelSprite name="ship" color="var(--ink)" size={4.5} />
              </div>
            </div>

            {/* Steer Buttons */}
            <div className="absolute right-4 top-1/2 -translate-y-1/2 flex flex-col gap-2 z-25">
              <button
                onClick={() => setShipY(prev => Math.max(22, prev - 8))}
                className="arcade-btn alt font-pixel text-xs p-3 rounded-lg cursor-pointer"
                title="Steer Up"
              >
                ▲
              </button>
              <button
                onClick={() => setShipY(prev => Math.min(78, prev + 8))}
                className="arcade-btn alt font-pixel text-xs p-3 rounded-lg cursor-pointer"
                title="Steer Down"
              >
                ▼
              </button>
            </div>

          </div>

        </div>

        {/* Compact Right Tremor Telemetry */}
        <div className="border-2 border-[var(--dim)] bg-[var(--fld)] rounded-xl p-2.5 flex flex-col justify-between overflow-hidden shadow-sm">
          <div className="space-y-2">
            <div>
              <div className="font-pixel text-[9px] uppercase text-[var(--ink)] font-bold border-b border-[var(--line)] pb-1 mb-2">
                Hand Tremor (DCD)
              </div>

              <div className="bg-[var(--scr)] p-2 rounded-lg border border-[var(--line)] shadow-inner">
                <svg className="w-full h-10 text-[var(--good)]" viewBox="0 0 100 24" preserveAspectRatio="none">
                  <polyline
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2.5"
                    points={sparklinePoints}
                  />
                </svg>
              </div>

              <div className="font-terminal text-sm text-[var(--good)] font-bold mt-1.5 flex items-center gap-1.5">
                <span>✓ Low Jitter Steady (σ: 0.06)</span>
              </div>
            </div>

            <div className="border-t border-[var(--line)] pt-2 space-y-1">
              <div className="font-pixel text-[9px] uppercase text-[var(--ink)] font-bold">
                Eye Pursuit
              </div>
              <p className="font-terminal text-base font-medium text-[var(--ink)]">
                Smooth Track · {m2CatchUpJumps} catch-up saccades
              </p>
            </div>
          </div>

          <div className="pt-2 border-t border-[var(--line)]">
            <button
              onClick={nextStep}
              className="arcade-btn glow-guide text-[10px] py-2 w-full flex items-center justify-center gap-1.5"
            >
              <span>View Pilot Card</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>

      </div>

      {/* Slim Bottom Status */}
      <div className="flex items-center justify-between px-2 text-xs font-terminal text-[var(--dim)]">
        <span>Arduino Analog Read &amp; Intention Tremor Telemetry Active</span>
        <span>Mission 2 of 2</span>
      </div>

    </div>
  );
};

import React from 'react';
import { useArcade, STEP_NAMES } from '../../context/ArcadeContext';
import { Check, X } from 'lucide-react';

interface VerticalStepperProps {
  isOpen: boolean;
  onClose: () => void;
}

export const VerticalStepper: React.FC<VerticalStepperProps> = ({ isOpen, onClose }) => {
  const { currentStep, goToStep } = useArcade();

  if (!isOpen) return null;

  return (
    <aside className="w-56 sm:w-64 bg-[var(--body)] border-r-2 border-[var(--bezel)] flex flex-col justify-between p-3 select-none z-30 transition-all duration-200 shadow-xl overflow-y-auto">

      {/* Sidebar Header */}
